pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1346: Harmonic-Residual Coupling
    // Objectives:
    // 1. Minimize post_residual (Best Fit).
    // 2. Penalize "near-miss" dead space (residuals that cannot fit common item sizes).
    // 3. Prioritize packing next_item_size if possible.
    // 4. Use fitting_bins_count to prevent excessive fragmentation.

    let mut score = post_residual as f64;

    // Penalty for creating dead space that cannot fit typical items (10..80 range)
    // If post_residual is small but not zero, it's often better to open a new bin
    // unless the next item fits perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for preserving compatibility
        } else {
            score += 15.0; // Penalize closing the door on the next item
        }
    }

    // Harmonic class logic: penalize residuals that are not multiples of common item sizes (e.g., 20, 25, 33)
    // to keep bins "cleaner" for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // Fragmentation control:
    // If this is the only bin that fits, we are forced to use it.
    // If there are many fitting bins, we can afford to be more selective.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 0.1;
    }

    // New bin candidate handling:
    // If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if the current "best" fit is poor (post_residual is large).
    if bin_residual == bin_capacity {
        // High threshold for opening a new bin: only open if current bins are heavily cluttered
        // or if the item is large.
        score = 45.0 + (item_size as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals to prioritize tight packing.
    // We favor bins that leave the smallest post_residual (Best Fit).

    // 2. Lookahead Penalty: If the next item exists, penalize bins that cannot accommodate it
    // if the current post_residual is too small to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that can fit the next item perfectly (Best Fit for next item)
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // 3. Global State: Penalize opening a new bin if other fitting bins exist, 
    // unless the current bin is very efficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin significantly if we have options
            score += 45.0 + (mean_residual * 0.5);
        } else {
            // If no bins fit, we must open a new one; keep score neutral
            score = 20.0;
        }
    } else {
        // 4. Dead Space Avoidance: Penalize residuals that are too small to fit any common item (e.g., < 10)
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        // 5. Balance open bins: If we have many open bins, prioritize packing into existing ones
        // to keep open_bins_count low.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead zones" (small residuals that are unlikely to fit future items)
    // We heavily penalize residuals between 1 and 9 as they are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If this is a new bin, apply a threshold based on progress and current fragmentation.
    // Opening a new bin is expensive early on, but potentially necessary if current bins are poorly packed.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high to encourage filling existing ones.
        score = 65.0 + (mean_residual * 0.5);
        // If we are near the end of the stream, prioritize closing bins.
        score += (1.0 - progress) * 20.0;
    } else {
        // Best-Fit strategy: Prefer bins that result in smaller residuals (Best-Fit logic).
        // Penalty for leaving a large gap that doesn't fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }

        // Penalty for spreading items too thin across many bins.
        score += (open_bins_count as f64) * 0.5;

        // If this is the last bin that can fit the item, prioritize it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Adjust score based on the global mean residual to discourage filling bins that are already 
    // significantly emptier than the average (which keeps fragmentation balanced).
    if bin_residual < bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
