    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead zones": If post_residual is small but > 0, it's hard to fill.
    // Penalize residuals that are too small to fit the smallest expected items (approx 10-15).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global State: If we have many open bins, prioritize tightening existing ones.
    // If few bins are open, we can be more selective.
    score += (open_bins_count as f64) * 0.5;

    // 5. Dynamic Time Horizon: As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. New Bin Thresholding: If this is an empty bin (new bin candidate), 
    // only choose it if the current best fit is objectively terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, but decreases if fitting_bins_count is low.
        // If we have no bins that can fit, we are forced to open one.
        if fitting_bins_count == 0 {
            score = -100.0; 
        } else {
            // Otherwise, heavily penalize opening a new bin unless existing bins are very full.
            score = 60.0 + (mean_residual * 0.5);
        }
    } else {
        // 7. Favor bins that are already "tight" compared to the mean.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
