        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Encourage opening if no other choice exists.
        }
    }

    // 5. Global Balancing: If we have many open bins, penalize creating more.
