pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit principle), but penalize 
    // tiny gaps that are unlikely to be filled later in the stream.
    // We add a non-linear penalty for "dead space" that scales with stream progress.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that keep the mean residual balanced to prevent bin fragmentation.
    // We penalize deviation from the mean_residual to encourage uniform bin usage.
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: If the next item is large, prioritize leaving enough space.
    // If the next item is small, we are less sensitive to tight fits.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // New bin threshold adjustment: 
    // If this is a new bin (bin_residual == bin_capacity), score it based on 
    // the difficulty of fitting the item into existing bins.
    let mut score = post + dead_space_penalty + balance_penalty + lookahead_penalty;

    if bin_residual == bin_capacity {
        // Only open a new bin if the existing fits are objectively poor (high mean_residual)
        // or if we are late in the stream and need to clear out open bins.
        score = (mean_residual * 0.8) + (progress * 20.0);
    } else if fitting_bins_count == 1 {
        // If this is the only bin that fits, prioritize it heavily by reducing the score.
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (avoid fragmentation)
    // We favor bins that leave less space.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps after the next item is placed
        score -= (100.0 - diff) * 2.5;
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Mean Residual Balancing: If the bin is currently "emptier" than the average,
    // prioritize filling it to keep the average residual low and consistent.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0 * ((bin_residual as f64) / mean_residual);
    }

    // 5. New Bin Threshold: If considering a new bin (bin_residual == capacity),
    // heavily penalize it unless the existing options are extremely poor.
    if bin_residual == bin_capacity {
        score += 85.0; 
        // Penalize opening new bins based on how far we are into the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit the smallest possible 
    // items (assume 10), it is highly undesirable as it creates "wasteland".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize bin choice if it 
    // makes the next item impossible to fit in this bin, specifically if the current 
    // choice leaves a gap that is slightly too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, penalize based on current count.
    // We want to consolidate items into fewer bins.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. Threshold for opening new bins: 
    // If the bin is new, only favor it if all existing bins result in very poor fit (large post_residual).
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high to encourage filling existing ones.
        score = 40.0 + (mean_residual * 0.2);

        // If we are at the end of the stream, opening a new bin is very expensive.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 5. Best-Fit refinement: If multiple bins can fit the item, prioritize the one 
    // that leaves the smallest residual (standard Best-Fit behavior).
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize creating tiny gaps (wastage) non-linearly: 
    // Small residuals are dangerous, but 0 is perfect.
    let wastage_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward packing into bins that are already "tight" to keep open bins count low.
    // We use mean_residual to gauge the global density.
    let density_alignment = (post - mean_residual).abs();

    // Lookahead logic: if next_item_size is large, favor leaving space for it.
    // If next_item_size is 0, we are at the end, so maximize current density.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residual (Best Fit).
    // Modulate with progress: as we approach the end, be more aggressive with packing.
    let mut score = post * (1.0 + progress * 0.5) + wastage_penalty + density_alignment + lookahead_penalty;

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the current state is highly suboptimal for all existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting bins are extremely poor fits
        // (i.e., they create large wastage or conflict with lookahead).
        score = 40.0 + (progress * 20.0);
    } else if fitting_bins_count == 1 {
        // If this is the only bin that fits, prioritize it heavily.
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small gaps that are unlikely to fit future items.
    // If the post_residual is small but > 0, it's a "sliver" that wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // 2. Lookahead Integration: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when existing ones are available.
    // If this is a new bin (bin_residual == bin_capacity), add a cost proportional to open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If there are other bins that can fit the item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Global Efficiency: If the current bin's residual is significantly better than the mean,
    // favor it to keep the "good" bins compact.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive on the Best Fit (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Is this a new bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin unless we are forced or the mean_residual is very low (implying fragmentation)
        score = 85.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Best Fit logic base: prefer small post_residual
        // Penalize creating "dead zones" (post_residual < 10, as items are >= 10, 
        // unless it's a perfect fit)
        if post_residual > 0 && post_residual < 10 {
            score += 50.0;
        }

        // Lookahead heuristic: if next_item_size fits in the post_residual, reward this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }

        // Harmonic class logic: favor placements that leave residues that are multiples of 
        // common item sizes or align with the remaining mean_residual
        let harmonic_alignment = (post_residual as f64 % 20.0).abs();
        score += harmonic_alignment * 0.2;

        // If this is the only bin that fits, prioritize it strongly to avoid unnecessary new bins
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Dynamic thresholding based on stream progression
        score += (open_bins_count as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the remaining space.
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // prioritize this bin heavily to avoid leaving the next item for a new bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Efficiency scaling: As the stream progresses, prioritize filling existing bins
    // more aggressively to close out the process.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // 4. Global state awareness: If the current bin's residual is significantly better 
    // than the mean residual of open bins, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin logic: Only open a new bin (where bin_residual == bin_capacity) 
    // if the existing options are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but reduce it if we are 
        // effectively forced to (e.g., no bins fit or we are early in the stream).
        score = 60.0 + (progress * 20.0);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

