    // We penalize small post_residuals that are too small to fit common upcoming items.
    // As progress increases, we become more conservative about filling bins to avoid fragmentation.

    // Penalize creating "dead zones" (residuals < 10)
    let dead_zone_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large, avoid bins that leave a small gap
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 && post > 0.0 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // New bin bias: Only open a new bin if the current fit is extremely poor (large post_residual)
    // or if we are early in the stream and need to balance bin usage.
    let new_bin_bias = if bin_residual == bin_capacity {
        // High penalty for new bins to encourage filling existing ones, 
        // but decreasing as open_bins_count grows to prevent overflow.
        35.0 - (open_bins_count as f64 * 0.5) + (progress * 10.0)
    } else {
        0.0
    };

    // Interaction term: Prefer bins where the post_residual is close to the mean_residual
    // to maintain a uniform distribution of occupancy across bins.
    let uniformity_penalty = (post - mean_residual).abs() * 0.2;

    let score = post + dead_zone_penalty + lookahead_penalty + new_bin_bias + uniformity_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
