    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (small remaining space).
    // If post_residual is < 10, it's often a "dead" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for pairing current and next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Penalty if this bin cannot fit the predicted next item
        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, prioritize packing density over new bins.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin scaled by how many bins are already open
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 5. Mean Residual Balancing: If this bin's residual is significantly better than the mean, favor it.
        let residual_diff = post_residual as f64 - mean_residual;
        score += residual_diff * 0.2;
    }

    // 6. Last-Chance Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Non-linear coupling: punish empty space more severely as we near the end of the stream
    // to encourage higher utilization (packing tightness) when packing opportunities decrease.
    score += (post_residual as f64).powf(1.5) * (1.0 + progress);

    // Lookahead logic: if the next item is large, favor bins that have enough space left
    // to accommodate it (Best-Fit-Decreasing style)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Penalty for opening a new bin:
    // Only open if the existing fits are extremely inefficient (high mean_residual).
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Essential: must open a new bin
        } else {
            // High penalty for opening new bin when we could fit it elsewhere
            score += 150.0 * (1.0 - mean_residual / bin_capacity as f64);
        }
    } else {
        // Reward bins that bring the residual closer to the mean of other bins
        // to keep bin levels balanced (homogenization)
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score -= 5.0 * (1.0 / (1.0 + residual_diff));
    }

    // Final bias: prefer bins that are 'almost full' (post_residual near 0)
    // weighted by the scarcity of fitting bins
    score -= (10.0 / (fitting_bins_count as f64 + 0.1));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit behavior (minimize post_residual)
    // 2. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it is likely wasted space unless it fits a small item.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave residuals which are multiples of common item sizes.
    // This reduces fragmentation by aligning potential future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New bin thresholding: If no bin fits well, we force a new bin. 
    // We penalize the "New Bin" (bin_residual == bin_capacity) less if open_bins_count is low.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 5.0;
        } else {
            // Heavily penalize opening a new bin if other bins could have fit the item,
            // unless the current bins are very full (mean_residual is low).
            score += 40.0 - (mean_residual * 0.5);
        }
    }

    // 6. Final adjustment: Encourage filling bins that are already partially filled 
    // to keep the number of active bins low.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

