    }

    // 4. Tight fit reward: Prefer bins that are nearly full after placement
    // Best-fit-like behavior: smaller post_residual is usually better, 
    // unless it falls into the "dead space" trap handled above.
    score += (post_residual as f64) * 0.5;

    // 5. Global density balancing: If current bin is emptier than average, prioritize it
    // to keep the mean_residual stable.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

