        }
    }

    // 4. Global Balance: If the mean residual of open bins is high, 
    // try to fill bins to bring the average down.
    if mean_residual > (bin_capacity as f64 * 0.4) {
        score -= (post_residual as f64) * 0.2;
    }

    // 5. Progression Weighting: As the stream nears the end, 
    // become more aggressive in closing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
