    // wasteful. Penalize high residuals relative to the mean.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // We start with post_residual as the base, so the smallest post_residual is naturally prioritized.

    // 2. Lookahead Synergy: If post_residual perfectly accommodates the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward configurations where the next item fits snugly into the remaining space
        let tightness = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + tightness);
    }

    // 3. Fragmentation Penalty: Avoid creating "dead space" (small leftovers that can't fit any future items)
    // If post_residual is between 1 and 9 (since min item size is 10), it is effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // 4. Mean Residual Balancing: Penalize bins that deviate significantly from the mean of open bins
    // This helps keep the bin pack "level" to prevent creating one very full bin and many empty ones.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Urgency Calibration: If this is the only bin that fits, we are forced to use it.
    // We dampen the score if fitting_bins_count is low to ensure we don't open new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. New Bin Threshold: Discourage opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full)
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 is perfect, 100 is empty.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tight fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if we are forced to, or if the average residual is very high
        // (meaning existing bins are already too fragmented to be useful)
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // Reward keeping bins full
        score -= (bin_capacity - post_residual) as f64 * 0.1;

        // Lookahead: If next item fits in this post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Dynamic adjustment: As we approach the end of the stream, be more conservative
    // about opening new bins by increasing the penalty.
    if is_new_bin {
        score += (progress * 50.0);
    }

    // If this is the last chance for the item (only one bin fits it), 
    // significantly lower its score to prevent opening a new bin unless necessary.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Penalize fragmentation: If post_residual is small but > 0, it's often a "dead" space
    // unless it matches common item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the post-placement residual.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for common future items.
    // If post_residual is small but not zero, it creates "dead space".
    // We penalize values below 10 (likely unusable) quadratically.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 1.5;
    }

    // Lookahead influence: If next_item_size is large, favor bins that can accommodate it.
    // If the current bin cannot fit the next item after this one, add a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Stream progression coupling: 
    // As we approach the end of the stream, prioritize aggressive packing (lower residuals).
    // Early on, we can afford slightly higher residuals to keep future options open.
    score += (1.0 - progress) * (residual / bin_capacity as f64) * 5.0;

    // Penalty for opening a new bin prematurely.
    // If this is a new bin (residual == capacity) and there are existing bins that can fit the item,
    // apply a significant penalty to force using existing bins unless they are very poor fits.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0 * (1.0 + progress);
    }

    // Balance the number of open bins:
    // Penalize the creation of many bins if the mean residual is already high.
    score += (open_bins_count as f64 * mean_residual) / (bin_capacity as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Strongly penalize small gaps that are likely to become unusable
    // We target residuals that are smaller than the smallest possible items (often ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
