    // 4. Harmonic Alignment: Favor bins where the residual aligns with the mean_residual
    // This helps keep bins at similar fill levels, reducing variance
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.2;

    // 5. Progression Scaling: As we reach the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

