    // 4. Global Load Balancing: Penalize deviations from the mean residual to keep bins balanced.
    // This prevents creating one "very empty" bin and many "full" bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We add a slight bias against leaving very small, unusable gaps (e.g., 1-5).
    if post_residual > 0 && post_residual < 6 {
        score += 25.0;
