    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Reward is inversely proportional to the wasted space after placing the next item.
        score -= (50.0 - gap as f64) * 0.8;
