    // 3. New Bin Thresholding: Penalize opening a new bin unless it's strictly necessary
    // or the current open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one could hold it.
            score += 150.0 + (mean_residual * 2.0);
        } else {
