            score = 40.0;
        }
    }

    // 4. Density Balancing: If we are late in the stream, prioritize closing bins
    // by preferring bins that are already nearly full (low post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

