        score += deviation * 0.2;
    }

    // If this is the last chance for this item in existing bins, prioritize it
    // slightly more by reducing the score.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    // Heavily penalize opening a new bin if an existing bin could fit the item perfectly
    if is_new_bin && post_residual < 100 {
