    }

    // 5. Global Density Balancing: Penalize creating too many open bins if the mean residual
    // is already low (indicating we are packing tightly).
    if (open_bins_count as f64) > (total_items as f64 / 10.0) {
        score += mean_residual * 0.5;
    }

    // 6. New Bin Threshold: If evaluating a fresh bin (bin_residual == capacity),
    // apply a significant cost to discourage opening it unless no good fits exist.
    if bin_residual == bin_capacity {
        score += 85.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // 1. Penalty for creating "unusable" small gaps (dead space < 10, as items are >= 10)
    // If post_residual is < 10 and > 0, it's effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Penalty for opening new bins when space is available
    if is_new_bin {
        // Only open a new bin if we have too many open bins (high fragmentation pressure)
        // or if it's the absolute last resort (though the loop handles this).
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead heuristic: penalize placements that make the next_item impossible to fit
    // in the current bin if the next_item is large.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // 4. Tightness bias: If we have many fitting bins, prefer the one that leaves 
    // the least space (Best Fit), but penalize if the bin is already very full 
    // to keep it available for smaller items.
    if !is_new_bin && post_residual < 5 {
        score += 5.0;
    }

    // 5. Global pressure: As we near the end of the stream, prioritize clearing bins
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
