    };

    // If this is the only bin that fits, reduce its score to prioritize closure (Best-Fit logic).
    let urgency_bonus = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Base score: post_residual is the primary driver (Best-Fit).
    // We combine the non-linear penalties and bonuses.
    let mut score = post_res + dead_space_penalty + uniformity_penalty + lookahead_penalty + urgency_bonus;

    // Special handling for new bin (bin_residual == bin_capacity).
    // We only open a new bin if the current best score is very poor (high residual).
    if bin_residual == bin_capacity {
        score = 45.0 + (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
