    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Progression: As the stream nears completion, become more 
    // aggressive about filling remaining space to avoid opening new bins late.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 6. Fragmentation Avoidance: Penalize leaving small, unusable gaps (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more freedom as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 45.0 * (1.0 - progress * 0.5) } else { 0.0 };

    // Best-Fit Decreasing logic: penalize large post_residuals (wasted space).
    // Use a quadratic penalty to discourage leaving large gaps.
    let waste_penalty = post * post * 0.05;

    // Lookahead interaction: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "orphan" that bin.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalty is proportional to the size of the item we might fail to fit later.
        lookahead_penalty = (next_item_size as f64) * 0.8;
    }

    // Reward bins that have residuals close to the mean, promoting balanced usage.
    let balance_reward = (post - mean_residual).abs() * 0.2;

    // If this is the only bin that fits, reduce penalty to prevent unnecessary new bin creation.
    let urgency_discount = if fitting_bins_count == 1 && !is_new_bin { -20.0 } else { 0.0 };

    new_bin_penalty + waste_penalty + lookahead_penalty + balance_reward + urgency_discount
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

