    // 2. Harmonic Class Logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This aligns bin states with likely incoming item distributions.
    if post_residual % 20 == 0 { score -= 15.0; }
    if post_residual % 25 == 0 { score -= 12.0; }

