    }

    // 5. New Bin penalty: If we are considering a new bin, apply a heavy penalty unless the 
    // current bin residual is extremely poor (Best-Fit vs First-Fit tension).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open if no bins exist
        } else {
            // Only open a new bin if the current mean residual is already quite low
            // or if we are nearing the end of the stream.
            score += 45.0 + (mean_residual * 0.5);
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
