    // 3. Global Efficiency: If fitting_bins_count is 1, we are at a "last chance" for this bin.
    // Avoid opening a new bin (where bin_residual == bin_capacity) unless the fit is excellent.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if we have existing capacity
            score += 40.0;
        }
        // Normalize the new bin cost based on progression
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    // 4. Mean Residual Coupling: Penalize bins that deviate significantly from the mean 
    // usage of current bins to encourage uniform packing.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
