    }

    // 3. Dynamic New Bin Threshold: As the stream nears the end, become more conservative
    // about opening new bins.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        // If there are many open bins, penalize opening a new one unless necessary.
        score += open_bins_count as f64 * 2.0;
    }

    // 4. Balance the packing density: Penalize bins that deviate significantly from the mean residual.
    // This encourages a "Best Fit" behavior that keeps residuals uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Critical Constraint: If this is the last fitting bin, prioritize it to avoid
    // unnecessary bin expansion, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
