        // we reward this placement heavily to encourage "perfect pairing".
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64 * 0.8);
        }

        // 4. Fragmentation avoidance: Penalize residuals that are too small to hold 
        // common items but too large to be ignored (e.g., 1-9).
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }

        // 5. Mean residual alignment: Encourage bins to stay near the average residual
        // to keep the bin distribution uniform.
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;

        // 6. Last Chance logic: If this is the only bin that can fit the item, 
        // prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 7. Progress scaling: As the stream nears the end, become more aggressive 
    // about packing tightly to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
