    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical future items
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins unless the fit is excellent
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other options exist
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bins fit, normalize the cost
            score -= 10.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the current mean to keep bin usage density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progress weighting: Be more aggressive in filling bins as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

