    // 3. Mean Residual Balancing: Penalize bins that deviate significantly from the average
    // This keeps bin residuals clustered to increase the probability of future fits
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // 4. Strategic New Bin Threshold:
    // If we are forced to create a poor fit (high post_residual), check if it's better to open a new bin.
    // We penalize opening a new bin if we have plenty of open bins, but reward it if current bins are "clogged".
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if there are other options
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other options, this is a necessary cost
            score -= 10.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with packing (Best Fit)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
