pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for leaving a "sliver" (fragmentation):
    // If post_residual is small but > 0, it is likely wasted space.
    // We penalize values < 10 exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post as f64) * 5.0;
    }

    // Lookahead logic: If next_item_size is large, favor keeping larger residuals.
    // If next_item_size is small, prioritize filling current bin tightly.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if next_item > post {
            // If the next item won't fit here, we prefer smaller residuals now 
            // (Best Fit) to avoid leaving too much empty space.
            score -= (next_item - post) * 0.5;
        } else {
            // If the next item fits, prioritize leaving just enough room for it.
            score += (post - next_item).abs() * 0.8;
        }
    }

    // Adaptive thresholding: As we approach the end of the stream, 
    // become more aggressive about filling bins (Best Fit) to reduce open_bins_count.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Heuristic coupling with mean_residual:
    // If this bin's post_residual is significantly better than the global mean, 
    // reward it to encourage consolidation.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.2;
    }

    // Penalize cases where we have many options (fitting_bins_count > 1) 
    // but the bin is very inefficient (high post_residual).
    if fitting_bins_count > 1 {
        score += post * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
