        score += progress * 50.0;
    } else {
        // 5. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 6. Mean Residual Correction: Favor bins that align with the global average efficiency.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit)
    // We add a penalty for creating "dead space" (gaps < 10, since min item size is 10)
    let mut score = post;
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - post / 10.0);
    }

    // Dynamic penalty for opening new bins:
    // As the stream progresses, we want to be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // High cost to open a new bin, weighted by how many bins are already open
        // and current progress.
        score += 45.0 + (open_bins_count as f64 * 2.5) + (progress * 20.0);
    }

    // Lookahead interaction:
    // If the next item is large, prioritize keeping space available.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        // If this bin cannot fit the next item anyway, it is a slightly better candidate
        // for "dumping" the current item if post_residual is small.
        if (post_residual as f64) < next_f {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Balance the mean residual:
    // Penalize bins that deviate significantly from the mean residual of other open bins
    // to keep the packing density uniform.
    let dev = (post as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Last chance logic:
    // If this is the only bin that can fit the item, heavily prioritize it to avoid
    // unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

