            // Penalize opening new bins when space is available.
            score += 45.0;
        }
    }

    // 6. Balance the number of open bins vs mean residual.
    // If we have many open bins, we want to consolidate by favoring lower residuals.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // 7. Progression factor: As we near the end of the stream, prioritize 
    // filling current bins more aggressively to avoid trailing new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
