    // As progress approaches 1.0, we become more tolerant of small residuals
    let emptiness_penalty = (bin_capacity as f64 - post) * (1.0 - progress);
    score += emptiness_penalty;

    // Interaction term: If the next item is large, prioritize leaving more space
    // in the current bin if possible, or prioritize tighter fits now.
    if next_item_size > 0 {
        let fit_margin = post as f64 - next_item_size as f64;
        if fit_margin < 0.0 {
