            score -= (fit_margin.abs() * 0.5);
        } else {
            // Next item fits, reward bins that leave just enough space
            score -= (next_item_size as f64 / (post + 1.0));
        }
    }

    // Heuristic for new bin vs existing:
    // If it's a new bin (bin_residual == bin_capacity), calculate a "barrier" cost
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (already wasting space)
        // or if we have very few bins open.
        score += (mean_residual * 0.8) + (open_bins_count as f64 * 0.2);
    } else {
