        // because we want to preserve flexibility for future items.
        if fitting_bins_count == 1 {
            score -= 5.0; 
        }
    }

    // Non-linear coupling: penalize high residual variance if progress is high
    score += (post - mean_residual).powi(2) * progress * 0.01;

    score
}

