    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the post_residual can perfectly or nearly perfectly 
    // accommodate the next item, prioritize this bin highly.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 40.0;
        } else if diff < 5 {
            score -= 20.0;
        }
    }

    // 3. Balancing: Avoid opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // heavily unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Mean residual alignment: Prefer bins that keep the overall average residual 
    // usage consistent with the bin capacity.
    let residual_penalty = (post_residual as f64 - mean_residual).abs() * 0.1;
    score += residual_penalty;

    // 5. Progression awareness: As the stream nears the end, prioritize filling 
    // existing bins to clear them out (avoid orphaned space).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // 1. Base cost: The post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead zones": If post_residual is small but > 0, it's hard to fill.
    // Penalize residuals that are too small to fit the smallest expected items (approx 10-15).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global State: If we have many open bins, prioritize tightening existing ones.
    // If few bins are open, we can be more selective.
    score += (open_bins_count as f64) * 0.5;

    // 5. Dynamic Time Horizon: As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. New Bin Thresholding: If this is an empty bin (new bin candidate), 
    // only choose it if the current best fit is objectively terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, but decreases if fitting_bins_count is low.
        // If we have no bins that can fit, we are forced to open one.
        if fitting_bins_count == 0 {
            score = -100.0; 
        } else {
            // Otherwise, heavily penalize opening a new bin unless existing bins are very full.
            score = 60.0 + (mean_residual * 0.5);
        }
    } else {
        // 7. Favor bins that are already "tight" compared to the mean.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, but we want to minimize it (Best Fit).
    // We add penalties for creating "fragile" bins (low post_residual).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin:
    // We only open a new bin if the gain from doing so outweighs the cost of waste.
    // The cost of a new bin increases as the stream progresses (to prevent fragmentation early).
    if is_new_bin {
        score += (bin_capacity as f64 * 0.4) + (progress * 20.0);
    } else {
        // 2. Penalize poor fits in existing bins:
        // A post_residual that is small but non-zero is often worse than a larger one
        // because it leaves "dead space" that cannot fit future items.
        // We define 'unusable' space as anything < 10 (min item size is usually 10).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }

        // 3. Lookahead coupling:
        // If the next item is large, favor bins that can accommodate it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 4. Global balance:
    // If we have many open bins, penalize opening more to encourage consolidation.
    if is_new_bin {
        score += (open_bins_count as f64).powf(1.2) * 2.0;
    }

    // 5. Mean residual coupling:
    // Discourage bins that deviate significantly from the average residual of open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We favor bins that leave very little space (Best-Fit)
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Harmonic Coupling:
    // If next_item_size is known, penalize residuals that are too small to fit the next item
    // but large enough to be wasted (The "Dead Zone").
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot take the next item
            score += 50.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        } else {
            // Reward creating a residual that fits the next item perfectly (modulus alignment)
            let remainder = post_residual % next_item_size;
            score -= 15.0 * (1.0 - (remainder as f64 / next_item_size as f64));
        }
    }

    // 3. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only accept it if the current best open bin is "too full" to be useful for future items.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or the mean residual is very low
        score += 45.0 + (open_bins_count as f64 * 0.5);
        if mean_residual > 20.0 {
            score -= 20.0;
        }
    } else {
        // If fitting_bins_count is 1, this is the only bin that can take the item.
        // Heavily incentivize using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // 4. Progression weighting:
    // As we approach the end of the stream, prioritize packing tighter (minimize new bins)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: The residual space after placement.
    // We want to minimize this (Best Fit strategy).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space":
    // If the post_residual is smaller than the smallest possible item (10), 
    // it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // Lookahead logic: If the next item cannot fit into this post_residual,
    // we penalize this placement to encourage saving the space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // New bin penalty: Heavily penalize opening a new bin unless necessary.
    // As we approach the end of the stream, we become more aggressive in opening new bins
    // to avoid leaving large gaps in existing bins.
    if is_new_bin {
        let open_penalty = 60.0 * (1.0 - progress);
        score += open_penalty + (open_bins_count as f64 * 2.0);
    }

    // Pressure normalization: If we have many open bins, we discourage adding to them
    // if the resulting fit is poor, favoring tight packing or new bins if they are cleaner.
    if !is_new_bin && open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // Final adjustment: Penalize bins that deviate significantly from the mean_residual
    // to keep the bin fill-levels balanced (load balancing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

