    };

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the penalty for poor fits to prevent premature new bin opening.
    let desperation_factor = if fitting_bins_count == 1 { 0.5 } else { 1.0 };

    // Primary score:
    // 1. Post-residual: Prefer smaller residuals (Best Fit).
    // 2. Dead space penalty: Avoid creating tiny slivers.
    // 3. Lookahead: Incorporate future item constraints.
    // 4. New bin logic: If bin_residual == bin_capacity, this is the "new bin" case.
    //    We assign it a baseline cost that increases as we find better fits in existing bins.
    let mut score = (post * 1.2) + (dead_space_penalty * desperation_factor) + (lookahead_penalty * desperation_factor);

    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Penalize opening a new bin unless existing bins are very full.
        score = 85.0 - (mean_residual * 0.5) + (progress * 15.0);
