        // This helps maintain a balance across all open bins.
        if post_res < mean_residual {
            score -= (mean_residual - post_res) * 0.5;
        }
    }

    // Non-linear coupling: penalize bins that are "too empty" relative to the number of open bins,
    // encouraging consolidation as the stream progresses.
    let density_penalty = (open_bins_count as f64 * 2.0) * progress;
    score += density_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual). 
    // New bin penalty: If we are not forced to open a new bin, penalize the empty bin state.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0;
    }

    // 2. Harmonic Class Logic: Penalize remainders that are "useless" (too small for common items).
    // Small gaps (1-9) are often dead space; punish them unless the bin is perfectly filled.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 0.5);
    }

    // 3. Lookahead Logic: If the next item is large, favor keeping bins with more capacity open.
    // If next_item_size is large (> 50), penalize bins that would result in a tight fit (< 10).
    if next_item_size > 50 && post_residual < 15 {
        score += 15.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize creating a new one (high entropy).
    // If we have few open bins, favor filling the current ones to maintain high mean_residual.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 5. Modulo-based "Harmonic" Pressure:
    // Favor residuals that align with common divisors of 100 (20, 25, 50) 
    // to keep bins flexible for future items.
    if post_residual % 25 == 0 {
        score -= 5.0;
    } else if post_residual % 20 == 0 {
        score -= 3.0;
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing open bins 
    // (tighten the fit requirement).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are "unusable" 
    // (cannot fit the smallest reasonable items, typically < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, avoid creating a post_residual 
    // that is just slightly too small to fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If bin is empty (new bin candidate), apply a heavy penalty based on current open count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
    } else {
        // Reward filling existing bins to reduce total open bin count.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity/Bottlenecking: If this is the only bin that fits, prioritize it heavily
    // to avoid triggering the "new bin" penalty unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression Bias: As we approach the end of the stream, be more aggressive 
    // about filling bins tightly to avoid trailing empty space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize the gap left in the bin.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If next_item_size fits in post_residual, 
    // heavily reward this bin to keep it tightly packed.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (100.0 - (post_residual - next_item_size) as f64) * 2.0;
    }

    // 3. Prevent fragmentation: If this is the only bin that fits the current item,
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Mean residual balancing:
    // If this bin's post_residual is significantly better than the global average, 
    // prioritize it to maintain density.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Penalty:
    // Make opening a new bin expensive unless the fit is perfect (0 residual).
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score = 10.0; // Accept perfect fit in new bin
        } else {
            score = 150.0 + (post_residual as f64 * 2.0); // Harsh penalty for suboptimal new bins
        }
    }

    // 6. Progressive tightening: 
    // As the stream progresses, prioritize closing bins by favoring smaller residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
