    }

    // 4. Global State Awareness: If there are many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        // If other bins could fit the item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 5. Residual Balancing: Penalize bins that deviate significantly from the mean residual.
    // This helps keep filling patterns consistent across the bin set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish large post_residual (Best Fit principle)
    // We want to minimize post_residual, so it stays as the primary term.
    let mut score = post;

    // Non-linear penalty for creating "dead space" (residuals < 10 are often unusable)
    // We add a penalty if the post_residual is in the "unusable" range (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we have a next item, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin
    // because it will force a new bin for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // about filling bins tightly (Best Fit) vs opening new ones.
    // If we are nearing the end, we penalize opening a new bin heavily.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalty for opening a new bin scales with progress
        score += 40.0 + (30.0 * progress);

        // If there are other bins that could fit this item, punish opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with mean_residual: if this bin is significantly worse than 
    // the average, penalize it to encourage balancing.
    let residual_diff = post - mean_residual;
    if residual_diff > 0.0 {
        score += 0.5 * residual_diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
