    // Dynamic thresholding based on stream progression.
    // As we approach the end, be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    // Penalize the "New Bin" candidate disproportionately to force consolidation 
    // unless the fit is truly abysmal.
    if bin_residual == bin_capacity {
        score += 40.0;
