        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state optimization: try to keep residuals uniform
    // Penalize bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // Favor filling existing bins if we are near the end of the sequence
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Heavily penalize opening a new bin unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Only open new if we have many open bins already or the current item is very small
        // This prevents fragmenting capacity too early
        score += 40.0 + (open_bins_count as f64 * 2.0);

        // If we are forced to open a new bin, make it less attractive unless necessary
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual).
