    // 4. Fitting Constraint: If this is the last chance for the current item, prioritize it
    // but only if it doesn't create a tiny dead-space fragment
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the residual is exactly 0, it's an optimal placement
    if post_residual == 0 {
        score -= 40.0;
    }

