    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force consolidation in later stages.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Best Fit Decreasing logic: favor small post_residual (tight packing).
    // Use a quadratic penalty for large residuals to favor compact bins.
    let fit_score = post * post / 20.0;

    // Lookahead logic: If the next item is large, favor bins that leave enough space
    // to accommodate it (anti-fragmentation).
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
