    // lower than the mean, it is a "tight" bin. Reward filling it further 
    // to keep the average empty space high in other bins.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progress Scaling: As the stream progresses, prioritize closing bins 
    // (stricter dead space avoidance) to avoid carrying empty capacity to the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
