    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), add a penalty based on open_bins_count
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Sensitivity: If the next item is large and this bin can't fit it, 
    // but another open bin might, penalize this bin slightly to preserve space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 5.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // heavily reward it to ensure the item is placed rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual balancing: Prefer bins that keep the mean residual closer to 
    // the target of half-capacity (50), preventing fragmented bins.
    let current_mean_impact = (post_residual as f64 - 50.0).abs() * 0.1;
    score += current_mean_impact;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We favor bins that leave little space (low post_residual).

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, 
    // significantly lower the score to prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit (post_residual == next_item_size)
            let diff = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 / (1.0 + diff));
        } else {
            // Penalize if the next item won't fit at all in this bin
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full)
        // or if we have no other good options.
        score += 60.0 - (mean_residual * 0.5);
    }

    // 4. Scarcity/Constraint Handling:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // fragmentation or overflow issues.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Bias:
    // As the stream nears the end, become more aggressive about filling existing bins
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin with very little space left (fragmentation)
    // We want to avoid residuals that are too small to fit common items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Global state: if we have many bins open, penalize opening a new one
    // If bin_residual == bin_capacity, we are evaluating a new bin
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 60.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    } else {
        // If this is the last fitting bin, reward picking it to avoid opening a new bin later
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Encourage balanced usage: penalize bins that deviate far from the mean_residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Dynamic horizon: as we approach the end of the stream, be more aggressive with packing
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

