    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As progress increases, we become more conservative about creating "dead" space.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * (1.0 + progress)
    } else {
