    // Reward post_residuals that are multiples of common item sizes (e.g., 20, 25)
    // This creates "bins for specific future items"
    let mod_penalty = (post_residual % 20) as f64;
    score += mod_penalty * 0.5;

    // 3. Lookahead Logic (Next Item Coupling)
    // If next_item_size fits in post_residual, drastically reduce score (prioritize this bin)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // Further reward if it fills the bin perfectly (Best Fit / Exact Match)
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 4. Density Balancing
    // Penalize bins that leave very small, unusable slivers (e.g., 1-9)
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // 5. Global state normalization
    // As the stream progresses, prioritize closing bins (lower mean_residual)
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 6. Final scaling for fitting constraint
    // If this is the only bin that can fit the item, give it a significant priority boost
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
