    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": bins with very small residuals are hard to fill later.
    // We apply a non-linear penalty to residuals that are between 1 and 9 (too small for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, prioritize keeping larger residuals open.
    // If the next item is small, prioritize tighter fits.
    if next_item_size > 0 {
        let lookahead_impact = (next_item_size as f64 / bin_capacity as f64) * 20.0;
        if post_residual < next_item_size {
            score += lookahead_impact;
        } else {
            score -= lookahead_impact * 0.5;
        }
    }

    // Progression coupling: As the stream nears the end, become more aggressive 
    // about filling bins to reduce the open_bins_count.
    score += progress * (open_bins_count as f64 * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that decreases as the stream progresses, but is generally high to prefer 
    // existing bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 - (progress * 15.0);
    }

    // Encourage balance: penalize bins that deviate significantly from the mean_residual
    // to keep bins roughly at the same capacity level (Best-Fit-like behavior).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    score
}

