    // as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    let mut score = post;

    // Penalty for creating a new bin: non-linear growth based on stream progress
    // We want to force consolidation early (progress ~ 0) and allow more flexibility later.
    if is_new_bin {
