}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin heavily.
    //    We prioritize filling the bin such that the remaining space is exactly or slightly 
    //    larger than the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
