    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly worse than the current average.
    if post_residual as f64 > mean_residual {
        score += 10.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // 5. New Bin Thresholding: Make opening a new bin expensive unless the best fit is truly terrible.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (the system is fragmented)
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

