    score += (remainder as f64).powf(1.1);

    // If this is a new bin, apply a significant penalty to encourage filling existing bins first,
    // unless the fit is extremely tight (Best-Fit principle emulation)
    if bin_residual == bin_capacity {
        score += 35.0;
        // Aggressively penalize opening a new bin if other bins can fit the item
        score += (fitting_bins_count as f64) * 25.0;
    }

    // Late-stage game strategy: as we approach the end of the stream,
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    // Prefer bins that are already "closer" to being full (lower residual)
    // to keep the number of active bins minimal (First-Fit Decreasing behavior).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

