    // Penalty for leaving "slivers" (dead space < 10) which are hard to fill given the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New bin cost: penalize opening a new bin unless necessary.
    // As progress increases, we become more conservative about opening new bins.
    if is_new_bin {
        score += 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: if the next item is large, favor bins that have enough space for it.
    // If post_residual is small but next_item_size is large, we might regret this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Interaction with mean_residual: favor bins that are closer to the current average 
    // to keep the bin landscape uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // If this is the last chance to fit an item in an existing bin, penalize the new bin option heavily.
    if is_new_bin && fitting_bins_count > 0 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

