    // 2. Harmonic Class Logic: Reward filling bins to specific modular thresholds
    // Aiming for "clean" remainders (e.g., 0, 20, 25, 50) that accommodate future items.
    let remainder_mod = (post_residual % 25) as f64;
    score += remainder_mod * 0.5;

