    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
    }

    // Best-Fit strategy: Favor bins that result in smaller post_residual
    // We apply a non-linear weight to the residual to punish fragmentation
    score += (post_residual as f64).powf(1.2);

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next known item
            score -= 25.0 * (1.0 - progress);
        } else if post_residual < 15 && post_residual > 0 {
            // Penalize "dead space" that is too small for any likely item (assuming 10-80 range)
            score += 30.0;
        }
    }

    // Global state awareness: If we have many open bins, prioritize tightening existing ones
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // If this is the only bin that fits, we must take it to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
