    // for the lookahead item (next_item_size) or match the mean residual to prevent fragmentation.

    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless existing options are extremely poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; 
    }

    // 2. Lookahead matching: If post_residual is close to next_item_size, reward this placement.
    // This reduces fragmentation by creating "perfect" fits for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 25.0 * (1.0 / (1.0 + diff));
    }

    // 3. Prevent "orphan" bins: If this is the only bin that can fit the item, 
    // it is highly valuable; reduce score to ensure it is picked.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. Entropy control: Discourage creating bins with residuals significantly 
    // smaller than the current mean residual, as this leads to unusable space.
    if (post_residual as f64) < (mean_residual * 0.5) && post_residual > 0 {
        score += 10.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post-residual (already in 'score').
    // 2. New Bin Penalty: Heavily penalize opening a new bin unless necessary.
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
        // Only open new if we really have no good fit elsewhere.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 3. Lookahead Logic: If next_item_size exists, penalize bins that leave insufficient space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: we can fit the next item in this same bin.
            score -= 25.0;
        } else if post_residual > 0 && post_residual < 15 {
            // Danger: creating a sliver of space likely to be wasted.
            score += 15.0;
        }
    }

    // 4. Global State Balancing: 
    // If mean_residual is high, we are being too loose; prioritize tighter fits.
    // If mean_residual is low, we are being too tight; allow slightly worse fits to avoid new bins.
    if !is_new_bin {
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        } else {
            score -= 5.0;
        }
    }

    // 5. Density heuristic: favor filling bins towards 100% as the stream nears the end.
    if progress > 0.8 && !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_residual as f64;

    // Penalty for creating small, unusable gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: favor bins that can accommodate the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Dynamic thresholding for opening new bins vs filling existing ones
    // As the stream progresses, become more aggressive at filling existing bins to reduce fragment count
    if is_new_bin {
        // Penalty for opening a new bin scales with progress and the number of already open bins
        let open_penalty = 15.0 + (open_bins_count as f64 * 2.0) + (progress * 50.0);
        score += open_penalty;
    } else {
        // Reward bins that bring the mean residual closer to a target "efficiency" (e.g., 10-15)
        // This encourages "leveling" the residuals across the set of active bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= 5.0 * (1.0 / (1.0 + deviation));

        // If this is the only bin that can fit the item, reward it highly to prevent unnecessary new bin creation
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Non-linear coupling: penalize high residual variance as the stream ends
    score += (progress * progress) * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins where post_residual is small (Best-Fit principle)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples or divisors 
    // of common item sizes (e.g., 20, 25, 33, 50).
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 15.0;
        }
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // 3. Lookahead Synergy: If next_item_size fits in the post_residual, 
    // reward this placement strongly (Two-item pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Scarcity/Density Balancing: 
    // If we only have one bin that fits, we are forced to use it. 
    // If it's a poor fit (high post_residual), we might prefer a new bin.
    if fitting_bins_count == 1 && post_residual > 30 {
        // High penalty for forced bad fits; encourages opening a new bin instead
        score += 50.0;
    }

    // 5. New Bin Thresholding: 
    // When evaluating a brand-new bin (bin_residual == bin_capacity),
    // apply a bias based on how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high; only do it if existing fits are terrible
        score = 60.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progressive Tightening: 
    // As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "dead zones" (gaps < 10) 
    // and maintaining low open_bins_count.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps too small for any likely item)
    // Small gaps (1..9) are essentially wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins unless necessary
    if is_new_bin {
        // High penalty for new bins to encourage filling existing ones.
        // Penalty scales with how many bins are already open.
        score += 35.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead: If we have a next_item, prioritize bins that leave space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly or nearly perfectly accommodate the next item.
            let slack = post_residual - next_item_size;
            score -= (100.0 - slack as f64) * 0.2;
        } else {
            // Penalize bins that would force a new bin for the next item.
            score += 15.0;
        }
    }

    // 4. Pressure: If only one bin can fit this item, prefer it to keep options open
    // but only if it doesn't create a "dead zone" (handled in step 1).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Balance residuals: Prefer bins that stay close to the current mean_residual
    // to keep the bin landscape uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin (if fitting_bins_count > 0)
    // We heavily penalize the "New Bin" candidate if there are existing bins that fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual is close to the next_item_size.
    // This minimizes future fragmentation by creating "perfect" fits for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if post_residual can perfectly accommodate the next item (diff == 0)
        // Penalize if the next item won't fit at all (post_residual < next_item_size)
        if post_residual < next_item_size {
            score += 20.0;
        } else {
            score -= (100.0 - diff) * 0.5;
        }
    }

    // 3. Efficiency heuristic: Penalize creating "dead space" that is too small for any item (e.g., < 10)
    // but reward bins that align with the current mean residual to keep bins balanced.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // 4. Global balance: If we have many open bins, prioritize filling the ones closest to the mean_residual
    // to prevent under-utilizing a large number of bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. Progression awareness: As the stream nears the end, prioritize tight packing (Best Fit)
    // over future-proofing, to close out remaining bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
