    // Residuals < 10 are often unusable given the item range [1, 100]
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization
    // If the next item can fit in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
