        // Further reward if it creates a near-perfect pack
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. Global state awareness
    // If this is a new bin (residual == capacity), penalize it based on how many
    // bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);

        // If we have many fitting bins, opening a new one is highly inefficient
        if fitting_bins_count > 0 {
