    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If a next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress.powf(0.5));
        }
    }

    // Dynamic thresholding: As the stream progresses, prioritize closing bins
    // by penalizing the creation of new bins (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let open_penalty = 40.0 * (1.0 - progress).powf(2.0);
        score += open_penalty;
    }

    // Interaction with mean_residual: Encourage packing tighter than the current average
    if post_res > mean_residual {
        score += 5.0 * (post_res - mean_residual) / bin_capacity as f64;
    }

    // Fitting density: If only one bin fits, prioritize it heavily to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We want to minimize the post_residual to pack tightly.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small (e.g., < 10), we create "slivers" that are hard to fill.
    // Penalize small slivers unless they are exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64);
    }

    // 3. Lookahead Synergy:
    // If a future item exists, check if the current post_residual can accommodate it.
    // If post_residual is just slightly too small for the next item, it's a "bad" placement.
    if next_item_size > 0 {
        if post_residual < next_item_size && (post_residual + item_size) >= next_item_size {
            score += 40.0;
        }
        // If post_residual fits the next item well, reward it.
        if post_residual >= next_item_size && post_residual < (next_item_size + 15) {
            score -= 15.0;
        }
    }

    // 4. Fitting Constraint:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // heavily bias towards using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Density Control:
    // As the stream progresses, prioritize closing bins to reduce open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 6. New Bin Penalty:
    // Heavily penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // unless the current fit is catastrophic.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are late in the stream, be even more conservative about new bins.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
