    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // The cost of opening a new bin increases as we approach the end of the stream.
        score += 20.0 * (1.0 + progress * 2.0);

        // Also penalize opening a new bin if there are existing bins that could fit the item.
