    // If the next item is large, favor bins that can accommodate it (smaller post_residual).
    // If the next item is small, favor bins that preserve larger residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0; // Penalize bins that will force a new bin for the next item
        } else {
            score -= 5.0; // Reward bins that keep the next item comfortably
        }
    }

    // 3. Harmonic Class Logic:
    // Reward bins whose residuals align with the mean density of the current open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. Scarcity/Efficiency weighting:
    // If we have many bins open, be more aggressive about filling existing ones (lower score for tight fits).
    // If we have few bins, be more selective to avoid packing items too tightly if it prevents future fits.
    if fitting_bins_count == 1 && post_residual > 0 {
        // This is the last chance to use this bin effectively
        score -= (100 - post_residual) as f64 * 0.2;
    }

    // 5. Normalization for "New Bin" candidate:
    // If bin_residual == bin_capacity, this is a fresh bin.
    // Apply a base cost to opening new bins that scales with the progress of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
