    }

    // 4. Density Balancing:
    // Prefer bins that are closer to the mean residual of all open bins to keep utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last resort optimization:
