    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive tightening:
    // As the stream progresses, prioritize closing gaps more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

