pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin creation exponentially as we approach the end of the stream
    // to force packing efficiency when few items remain.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (100.0 * (1.0 + progress.powi(2))) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Best Fit strategy: minimize post_residual, but penalize "near-empty" bins (dead space)
    // We use a quadratic penalty on the post_residual to favor tight packing.
    // If post_residual is very small (< 5), we reward it as a "perfect" fit.
    let mut score = post.powf(1.5);

