    }

    // Encourage filling bins that are already below the mean residual to keep 
    // the variance of open bins low.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    }

    // Apply the new bin penalty
    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
