    // we reward this placement heavily.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding based on stream progression:
    // As the stream progresses, become more aggressive at filling bins tightly 
    // to avoid leaving too many bins partially open.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // Heuristic for opening new bins:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are 'too full' to accommodate 
        // the next item efficiently, or if we are early in the stream.
        let penalty_for_new_bin = 25.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 0.2);
        score = penalty_for_new_bin;
    } else {
        // If it's an existing bin, reduce score based on how well it balances 
        // the average residual load.
        score -= (mean_residual - post) * 0.5;
    }

    // If this is the last chance for the current item, lower the score to ensure placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize small, unusable residuals (The "Dead Space" Penalty)
    // Residuals in the range [1, 9] are extremely difficult to fill given the input constraints.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization (Harmonic coupling)
    // If we have a next item, check if it fits in the current post_residual.
    // If it fits, we reward this bin heavily to keep the future item constrained.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // 3. Harmonic class alignment
    // Favor bins that result in residuals which are multiples of common item sizes (20, 25, 33).
    // This creates "bins of specific types" to maximize future density.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 4. Thresholding against new bin creation
    // If this is an empty bin (bin_residual == bin_capacity), it is the "New Bin" candidate.
    // We only select this if the cost of placing in existing bins is significantly high.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, scaled by how many bins are already open.
        score = 65.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this bin is the last chance for the current item, lower its cost to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression scaling
    // Towards the end of the stream, prioritize aggressive packing over bin-count balancing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
