    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Mean Residual Alignment: Favor bins that keep the mean residual balanced.
    // Penalize bins that deviate significantly from the current mean.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progress Weighting: As the stream nears the end, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
