            score -= 40.0;

            // Further reward if the residual after the next item is small (tight packing).
            let hypothetical_residual = post_residual - next_item_size;
            score += hypothetical_residual as f64 * 0.5;
        } else {
            // Penalty: This bin will NOT fit the next item.
            score += 20.0;
        }
    }

    // Balance against mean_residual:
    // If this bin's post-residual is significantly worse than the current average, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // Progression awareness:
    // As the stream nears completion, become more aggressive about filling bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.2;

    // Critical constraint: If this is the last chance for the current item, 
    // reduce the penalty for a poor fit to ensure the item is placed.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    score
}

