pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (very small residuals that are hard to fill)
    // Residuals in the range [1, 9] are statistically difficult to fill given item constraints (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Adaptive thresholding: As we approach the end of the stream, prioritize packing tighter
    // to avoid leaving too many bins partially full.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. If this is a new bin, penalize it unless it's strictly necessary.
    // The higher the fitting_bins_count, the more we should avoid opening a new bin.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64 * 15.0);
    } else {
        // 5. If we have many open bins, prioritize filling the one with the smallest residual (Best Fit).
        // If we have few open bins, prioritize keeping residuals balanced to allow more flexibility.
        if open_bins_count > 5 {
            score += (bin_capacity - bin_residual) as f64 * 0.1;
        } else {
            score -= (bin_capacity - bin_residual) as f64 * 0.05;
        }
    }

    // 6. Dynamic balance: penalize bins that deviate significantly from the mean_residual
    // to keep the bin landscape uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily early on, but allow flexibility as we near completion.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // 2. Penalize creating "dead space" (very small residuals) that are hard to fill later.
    // We penalize residuals in the range [1, 10] because they are unlikely to accommodate future items.
    if !is_new_bin && post_residual > 0 && post_residual < 12 {
        score += (15.0 - post_residual as f64) * 2.0;
    }

    // 3. Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 && post_residual < next_item_size {
