    }

    // 4. Global balance: If we have many open bins, prioritize filling them to consolidate.
    // We penalize opening a new bin if fitting_bins_count is high.
    if is_new_bin && fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 * 5.0);
    }

    // 5. Smooth non-linear interaction with mean_residual to avoid fragmentation.
    // If our post_residual is significantly worse than the mean, penalize it.
    if !is_new_bin && (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual).powf(1.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot accommodate common modulo-classes
    // We prioritize keeping post_residual as a multiple of 10 or 20 to increase packing density
