    } else {
        // Prefer bins that are already well-filled (lower mean_residual)
        // This encourages "Best Fit" behavior
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Final harmonic calibration: penalize small residuals that are unusable (< 10)
    if post_residual < 10 && post_residual > 0 {
