    // 4. Mean residual alignment: Prefer bins that stay close to the average utilization to prevent 
    // creating extreme outliers in bin fullness.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // We heavily discourage opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead optimization (Next-Fit-Best-Fit hybrid):
    // If we have a next item, we want the current post_residual to be as close 
    // to next_item_size as possible (to minimize fragmentation).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.4;

        // Penalize if the next item cannot fit in the post_residual at all.
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. Global Packing Efficiency:
    // If the post_residual is smaller than the mean_residual of other bins, 
    // it suggests we are packing more tightly than average. Reward this.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 4. Criticality constraint:
    // If this is the ONLY bin that can fit the item, we should be more 
    // lenient with the score to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins 
    // (making post_residual as small as possible).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
