        }
    } else {
        // 3. Fragmentation avoidance: Penalize leaving tiny unusable slivers
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // 4. Global balance: If many bins are open, favor filling existing bins
        // to increase packing density.
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
