    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation): 
    // If post_residual is small but not zero, it's often unusable. 
    // We penalize values < 10 exponentially.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead coupling: If a second item is known, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
