    if bin_residual == bin_capacity {
        score += (capacity * 0.8) * (1.0 - progress * 0.5);
    }

    // Interaction with mean_residual: If current bin is significantly worse than 
    // the average bin, penalize it to encourage balancing.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // If this is the only bin that fits, significantly reduce its score (priority).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
