    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 5.0;
    }

    // 5. Mean Residual Stability:
    // Penalize bins that deviate significantly from the global mean residual to keep
    // bin levels balanced across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Progression Scaling:
    // As the stream progresses, prioritize closing bins (lower score) to finalize packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
