    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Empty Bin Thresholding:
    // When considering a new bin (bin_residual == bin_capacity), only accept if
    // the current open bins are all "bad" fits (e.g., leaving a tiny unusable residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the state is forced.
        score += 30.0;

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Balance open bins:
    // Favor bins that align with the mean residual to keep bin states uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps 
    // that are too small for common items (e.g., < 10) or that don't fit the next item.

    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: 
    // If the post_residual is small but > 0, it's often a "dead zone". 
    // We penalize gaps in the (0, 10) range significantly as they are rarely usable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy:
    // If we have a next_item_size, we prioritize bins that can accommodate it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Bin Pressure Management:
    // Penalize opening new bins when current bins have high mean_residual.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If other bins can fit the item, heavily penalize opening a new one 
        // unless the mean_residual is already very low (bin packing efficiency).
        if fitting_bins_count > 0 {
            score += 40.0 - mean_residual;
        }
    }

    // 4. Best Fit Optimization:
    // Prefer bins that result in a tighter fit (smaller post_residual), 
    // but normalize by the progress of the stream to become more aggressive as we finish.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
