pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score: punish large post-residuals to encourage Best-Fit behavior.
    let mut score = post.powf(1.5);

    // Penalty for creating a "fragmented" bin: if the post_residual is too small to fit 
    // common items (e.g., < 15), add a penalty that scales with progress.
    if post > 0.0 && post < 15.0 {
