    }

    // Lookahead logic: if next_item_size is large and won't fit in current post,
    // penalize this placement to keep space open for the next item.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += (next_item_size as f64 - post).powf(1.2) * 2.0;
    }

    // New bin bias: if this is a new bin (residual == capacity), 
    // only choose it if the current best fit is objectively terrible.
    if residual == capacity {
        // High penalty for opening a new bin early in the stream.
        // As we approach the end of the stream, the penalty decreases.
        score += (capacity * 0.5) * (1.0 - progress).powi(2);

        // If many bins are already open, opening another is costly.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward filling bins that are already below the mean residual to consolidate.
        if residual < mean_residual {
            score -= (mean_residual - residual) * 0.5;
        }
    }

    // If this is the last chance for the item (only one bin fits), 
    // reduce the penalty to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && residual != capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
