    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (bins that are too small to fit common items)
    // We penalize post_residual heavily if it's small but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // we prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Dynamic threshold: As the stream nears completion, favor filling existing bins
    // to avoid leaving partially filled bins at the end.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing capacity
            score += 40.0 + (progress * 50.0);
        } else {
            // Necessary to open new bin, add slight bias to keep it clean
            score -= 5.0;
        }
    } else {
        // Encourage balanced usage across open bins
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Strategic constraint: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for leaving "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residual values that fall in the [1, 19] range (since min item size is 1).
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powf(1.5);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If next_item_size > post_residual, we penalize this bin for being too tight.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize aggressive consolidation.
    // We discourage opening new bins (bin_residual == bin_capacity) as progress approaches 1.0.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 + progress.powf(2.0));
    }

    // Global state coupling: if many bins are open, penalize creating another one
    // by increasing the cost of the empty bin relative to the mean residual.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
    }

    // Reward bins that bring the bin residual closer to the global mean residual (homogenization).
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing the post_residual (tightest fit).
    // The base score starts at post_residual.

    // 2. Harmonic Class Penalty: If the post_residual is small (e.g., 1-5), it creates "dead space"
    // that cannot fit most items (min size 10). Penalize these "sliver" residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead synergy: If the next item fits into the remaining space, reward this bin.
    // This effectively implements a Best-Fit-Lookahead strategy.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Empty Bin Threshold: When considering a brand-new bin (bin_residual == bin_capacity),
    // only accept it if open bins are exhausted or if all existing bins create poor fits.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open a bin
        } else {
            // Penalize opening a new bin unless the mean residual of current bins is very low,
            // suggesting they are all nearly full and inefficient for the current item.
            score = 35.0 + (mean_residual * 0.5);
        }
    }

    // 6. Progression scaling: As the stream nears the end, become more aggressive 
    // about closing bins by penalizing new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // typically too small to be useful (1..9), as they create "fragmentation".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, 
    // reward this bin heavily to facilitate tighter packing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when current bins are already 
    // underutilized. If this is a new bin (bin_residual == bin_capacity), 
    // increase cost based on total open bins to discourage proliferation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If we have other options, make the new bin very expensive
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // 4. Prefer bins that keep residuals close to the global mean to maintain 
        // uniformity and reduce variance in bin utilization.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.5;
    }

    // 5. Finality heuristic: Near the end of the stream, prioritize aggressive 
    // filling of existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals to keep bins tightly packed.
    // However, heavily penalize leaving a residual smaller than the smallest likely item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New bin penalty: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist.
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No options, neutral score.
            score = 40.0;
        }
    }

    // 4. Balance current bin usage vs global state: 
    // If post_residual is significantly higher than the global mean_residual, 
    // it indicates a poor fit; penalize it to encourage using bins closer to the mean.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals to keep bins tight.
    // 2. Dead-space penalty: if the post_residual is small but > 0, it's often unusable.
    //    We penalize specifically residuals in the range [1, 9] as they are rarely filled.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: if a future item fits into the current post_residual,
    //    we reward this placement significantly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Global state: if the bin is brand new (residual == capacity), penalize opening it
    //    unless we have no better options.
    if bin_residual == bin_capacity {
        score += 35.0;
        // As the stream progresses, make new bins slightly more expensive to prevent
        // fragmentation early on, but allow them if the fitting_bins_count is low.
        score += (step_index as f64 / total_items as f64) * 15.0;
    }

    // 5. Fitting constraint: if this is the only bin that fits, prioritize it heavily
    //    regardless of the post_residual quality (avoid unnecessary new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Balance: penalize bins that deviate far from the mean_residual to keep
    //    the distribution of space usage uniform across open bins.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 significantly.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If a known next item fits into the current post_residual,
    // we prioritize this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic thresholding: As the stream progresses, be more conservative about 
    // opening new bins. If this is a new bin (residual == capacity), penalize it
    // based on how many bins are already open and how much space is wasted elsewhere.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options
        let new_bin_penalty = 15.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
        score += new_bin_penalty;
    } else {
        // Reward bins that keep the mean_residual aligned with item_size patterns
        // This helps maintain a "balanced" set of bins.
        let deviation = (post as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // significantly lower the score to force the fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo logic: prioritize post_residuals that are multiples of common item sizes
    // Modulo 10 and 20 are common divisors in bin packing distributions
    let waste_penalty = (post_residual % 10) as f64 * 0.5;
    score += waste_penalty;

    // 3. Lookahead logic: If a bin can fit the next item exactly, heavily reward it.
    // If next_item_size is 0 (end of stream), ignore this.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_margin = post_residual - next_item_size;
        // Reward bins that leave exactly enough space for the next item
        score -= (100.0 - fit_margin as f64) * 0.8;
    }

    // 4. Threshold logic: Discourage opening new bins unless necessary
    // If bin_residual == bin_capacity, this is a "new bin" candidate
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if other bins exist
            score += 45.0 + (mean_residual * 0.2);
        }
    } else {
        // 5. Density heuristic: Reward filling bins to near-capacity
        // Penalize bins that would be left with "orphaned" space (e.g., < 10)
        // because items are >= 10.
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize gaps that are too small to fit typical future items (10..30)
    // If post_residual is small but > 0, it is likely unusable.
    if post_residual > 0 && post_residual < 15 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open bin pressure: Penalize creating new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other options, or if the current bins are too full to accommodate future items.
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            score -= 10.0;
        }
    }

    // 3. Lookahead integration: Favor bins that leave enough room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that can accommodate the next item.
        } else {
            score += 15.0; // Penalize bins that block the next item.
        }
    }

    // 4. Global efficiency: Favor bins that keep the mean_residual of the system low.
    // We want to pack items into bins that are already "tight".
    score += (post_residual as f64 - mean_residual) * 0.5;

    // 5. Stream progression: As we approach the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with a lookahead penalty.
    // We prioritize bins that result in the smallest post_residual (Best Fit),
    // but penalize the creation of "orphaned" space that cannot accommodate the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Only open a new bin if we are forced to, or if the current open bins 
        // are so fragmented that they cannot accommodate the lookahead item.
        if fitting_bins_count > 0 {
            score += 200.0; // Heavy penalty for opening new bin if space exists
        } else {
            score = 50.0; // Baseline cost for opening a new bin
        }
    } else {
        // Reward placements that leave a residual capable of holding the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Bonus for "perfect" alignment with next item
            } else if post_residual > 0 && post_residual < 10 {
                score += 40.0; // Strong penalty for creating tiny, unusable slivers
            }
        }

        // Favor bins that stay close to the global mean residual to keep fragmentation uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the last fitting bin, prioritize it to avoid opening a new bin later.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Progression weight: as we approach the end of the stream, prioritize tight packing
    // more aggressively to minimize trailing empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If the post_residual is < 10, it's often a "wasted" sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If we have a next item, penalize bins that cannot accommodate it
    // after placing the current item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Dynamic constraint: If this is the only bin that fits the current item, 
    // significantly lower its score to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Global state awareness: If open bins are becoming too fragmented (high mean_residual),
    // prioritize packing into existing bins to consolidate.
    if mean_residual > 30.0 {
        score -= 10.0 * (1.0 - progress);
    }

    // New bin logic: Opening a new bin is very expensive early on, 
    // but becomes a necessary evil as the stream progresses and fragmentation increases.
    if is_new_bin {
        score += 35.0 - (20.0 * progress);

        // If we have many open bins that already have enough space, penalize opening a new one.
        if open_bins_count > 5 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Heavily penalize opening a new bin early in the stream unless it is highly efficient.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * post;

    // Penalty for creating small, unusable gaps (dead space < 10, as items are >= 10).
    if post > 0.0 && post < 10.0 {
        score += 500.0 / post;
    }

    // Lookahead logic: If a future item is known, prioritize leaving enough space for it.
    if next_item_size > 0 {
        let gap_impact = (next_item_size as f64 - post).max(-20.0).powi(2);
        score += gap_impact * 0.5;
    }

    // Dynamic thresholding: As we approach the end of the stream, prioritize packing density
    // over maintaining open bins.
    let open_bin_penalty = if is_new_bin {
        // High cost to open new bins, but the cost decreases as we near the end of the stream
        // to allow for better packing of remaining items.
        (1000.0 * (1.0 - progress)) + (open_bins_count as f64 * 50.0)
    } else {
        // Reward fitting into existing bins based on how much they deviate from the mean.
        (post - mean_residual).abs() * 2.0
    };

    score += open_bin_penalty;

    // Final constraint: discourage leaving only one bin available if it creates a poor fit.
    if fitting_bins_count == 1 && !is_new_bin && post > 20.0 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We favor smaller post_residuals (tighter packing)
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If the next item can fit in the current post_residual,
    // strongly incentivize keeping that space open.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Avoid "Fragmenting": Penalize bins that would end up with very small, unusable residuals
    // (e.g., residuals < 10, since min item size is likely 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic thresholding: Favor bins that align with common modular denominators (e.g., 25, 50, 33)
    // This helps group items of similar sizes together.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 5. New-bin thresholding: Only open a new bin if the current fit is truly terrible
    // and we have many existing bins that are also nearly full.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;

        // If we are near the end of the stream, penalize opening new bins heavily
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;

        // If there are other bins that could have fit the item, discourage new bin creation
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 6. Global efficiency balance: If the average residual is very low, we are packing tightly.
    // Discourage opening new bins if the mean_residual is already small.
    if bin_residual == bin_capacity && mean_residual < 15.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
