    if open_bins_count > 5 {
        score += post_residual as f64 * 0.5;
    }

    // 5. If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Prefer bins that keep the mean residual balanced
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
