            score += 60.0; // Strong penalty to avoid opening new bins if existing ones work
        }
        // If it's the only option, don't penalize too much
        score += 10.0;
    }

    // 4. Balancing: Prefer bins closer to the mean residual to keep packing density uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 5. Progression awareness: 
    // As we approach the end of the stream, be more conservative about leaving empty space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

