pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "fragmented" space (too small for most items)
    // If post_residual is in [1, 9], it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit Decreasing logic: Favor bins that leave the least space
    // We already start with post_residual, which inherently favors tightest fit.

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the next item from forcing a new bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dynamic threshold: If we are near the end of the stream, 
    // be more aggressive in packing to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current packing is very inefficient
        // or if we have very few bins open.
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Balance the global residual: avoid having many bins with very low residual
    // by penalizing bins that fall significantly below the current mean.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
