    if post < mean_residual {
        score -= (mean_residual - post) * 0.2;
    }

    // If this is the last chance to fit the item in an existing bin, reduce the cost
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
