pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range) as they are hard to fill
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward keeping bins balanced relative to the mean residual
    let balance_score = (post_res - mean_residual).powi(2) * 0.1;

    // Incorporate lookahead: if the next item fits into the current post_residual, 
    // prioritize this bin more heavily.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Dynamic thresholding: as the stream progresses, become more aggressive 
