    }

    // 2. Open Bin Pressure: Penalize opening new bins when existing ones are available.
    // We heavily penalize the "New Bin" candidate if fitting_bins_count > 0.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0 * (open_bins_count as f64).sqrt();
    }

    // 3. Lookahead Synergy: If the next item can fit into the current post_residual,
    // reward this placement to keep the bin tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Mean Residual Balancing: If this bin's post_residual is significantly better 
    // than the current mean_residual of open bins, favor it to keep bin utilization balanced.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins to avoid leftover empty capacity.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want the post_residual to be as small as possible.

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, it is a high-quality placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit scenario: subtract score to favor this bin
            score -= (bin_capacity - post_residual) as f64 * 0.5;
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Cannot fit next item: penalize slightly
            score += 20.0;
        }
    }

    // 3. Prevent fragmentation:
    // Avoid leaving tiny residuals that are unlikely to fit future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Global state awareness:
    // If this is the last chance to fit the item in existing bins, favor it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New bin penalty:
    // If the bin is new, impose a high penalty unless it is the only option.
    if bin_residual == bin_capacity {
        score += 65.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Distribution normalization:
    // Slightly adjust based on how filled existing bins are on average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented by lookahead and bin density management.
    // Lower score is better.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (residuals < 10 are often unusable).
    // If the post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead: If the next item can fit in this bin, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Further reward if it fills the bin near capacity.
        if (post_residual - next_item_size) < 5 {
            score -= 10.0;
        }
    }

    // 3. Global State: If we are late in the stream, be more aggressive with packing.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. New Bin Logic: Discourage opening a new bin unless the current fit is poor.
    // bin_residual == bin_capacity identifies the "New Bin" candidate.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if the item is huge.
        let penalty = 20.0 + (open_bins_count as f64 * 0.5) + (item_size as f64 * 0.2);
        score += penalty;
    } else {
        // Favor bins that are already "half-full" to keep the mean_residual stable.
        let current_fill = (bin_capacity - bin_residual) as f64;
        score -= (current_fill / bin_capacity as f64) * 5.0;
    }

    // 5. If this is the only bin that fits, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, it's often better
    // to have a larger residual that can accommodate future items.
    // We penalize values of post_residual that are too small to fit common items 
    // but large enough to waste space (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item exists, penalize bins that cannot fit it
    // after the current item is placed.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 * (1.0 - progress);
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter (lower residual).
    // Early in the stream, we are more tolerant of opening new bins (keeping residuals high).
    score += (progress * 30.0) * (post_res / bin_capacity as f64);

    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // strongly discourage opening a new bin (which would have post_residual = 100 - item_size).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (1.0 - progress);
    }

    // Normalize against mean_residual to prevent bin variance
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

