    // Best-Fit logic: reward bins that become tightly packed
    // We favor post_residual being closer to 0 (tighter fit)
    // We add a penalty for opening a new bin if we have fitting options
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can still accommodate it
    // post_residual represents the space after current item. If it fits next_item_size,
    // we reward the placement (negative score shift).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // If the current placement forces a new bin later for the next item, penalize
            score += 20.0;
        }
    }

    // Harmonic class logic: penalize residuals that are not multiples of common item sizes 
    // or leave "dead" space that cannot fit common small items (like 10-20)
    let remainder = post_residual % 20;
    if remainder > 0 && remainder < 10 {
        score += 15.0;
    }

    // If this is the last chance for the current item, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Normalize by open bins to prevent excessive fragmentation as the stream progresses
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
