    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already
        // or if we have many fitting bins available.
        score = 30.0 + (open_bins_count as f64 * 0.5) + (fitting_bins_count as f64 * 5.0);
    } else {
        // If this is the last chance to fit the item in an existing bin, favor it.
