}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space: lower is better (Best Fit).
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..10) that are difficult to fill later.
    // We penalize post-residuals that are "dead zones" (e.g., < 10).
    if post < 10.0 && post > 0.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize keeping space open.
    // If next_item_size is large (> 50), penalize bins that would be too full.
    if next_item_size > 50 {
        score += (50.0 - post).max(0.0) * 0.5;
    }

    // Dynamic adjustment based on stream progression.
    // Late in the stream, we become more aggressive about filling bins tightly to avoid new ones.
    let tightness_bonus = (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;
    score -= tightness_bonus;

    // If this is the only bin that fits, we are forced to take it.
    // Reduce score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // Favor bins that align with the current mean residual to keep distribution uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
