    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins or the mean residual is already quite low,
        // suggesting that existing bins are too tight to accommodate future items effectively.
        if open_bins_count > 0 && mean_residual < 20.0 {
            score += 40.0; 
