    // 3. Lookahead Logic: If next_item_size fits in the post_residual, reward this bin heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
        // Further favor tight fits for the next item
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // 4. Thresholding: If this is the only fitting bin, accept it unless it's a very poor fit
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 20.0; // Encourage opening a new bin if the only fit is terrible
    }

    // 5. New Bin Logic: Discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Heavily penalize opening new bins if others exist
        } else {
            score = 10.0; // Base cost for new bin when no others fit
        }
    }

    // 6. Global State: Slightly prefer filling bins that are already "emptier" than the mean
    // to keep the bin distribution uniform
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

