        // If many bins are open, opening a new one is expensive.
        score = 25.0 + (open_bins_count as f64 * 0.5) + (progress * 10.0);

        // If we have other options, make the new bin very unattractive unless it's the only way.
        if fitting_bins_count > 0 {
