        }

        // Lookahead: If the next item is large, favor bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward bin that preserves room for the next item
            } else if post_residual < next_item_size && post_residual > 0 {
                score += 10.0; // Penalize bin that gets blocked for the next item
            }
        }

        // Global state: If the current bin is significantly tighter than the average, favor it (Best Fit).
        // If current residual is much higher than mean_residual, it is a "loose" bin; penalize it.
        if (bin_residual as f64) > mean_residual {
            score += 5.0;
        }

        // Near the end of the stream, prioritize closing bins to reduce total count.
        if progress > 0.9 {
            score -= (bin_capacity - post_residual) as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
