    // We use a quadratic term to aggressively punish "wasted" space in early bins
    let mut score = post * post * 0.01;

    // Favor bins that can accommodate the lookahead item
    // If the next item cannot fit in the post_residual, we penalize the current choice
    if next_item_size > 0 {
        if post_residual < next_item_size {
