    // Dynamic pressure: As the stream progresses, we want to tighten bin packing
    // to avoid leaving too many bins with small residuals that can't fit upcoming items.
    // If we are near the end of the stream, we prioritize minimizing open_bins_count.
    score += (open_bins_count as f64) * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), calculate an opportunity cost.
    // We only open a new bin if the existing fits are objectively terrible (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases as we fail to find
        // good fits in existing bins (represented by high mean_residual).
        score += 45.0 - (mean_residual * 0.2);
    } else {
        // Encourage filling bins that are already "half-used" to keep others empty
        // Subtract to reward placements that maintain a balanced mean_residual
        score -= (bin_capacity as f64 - post) * 0.1;
    }

    // Heuristic pressure to avoid creating "dead zones" (residuals < 10)
    // which are statistically hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
