    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is dynamic based on current average fullness.
        // If mean_residual is already very low, we are forced to open a new bin.
        score += (100.0 - mean_residual) * 0.5;

        // As we approach the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
