pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin. 
    // Lower residual is generally better (Best-Fit principle).
    let mut score = post_res;

    // Penalty for creating a "small" unusable gap (1..10) which is hard to fill.
    // Quadratic penalty peaks at small residuals to discourage slivers.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res).powi(2) * 2.0;
    }

    // Dynamic Lookahead coupling: 
    // If the next item cannot fit into this post-placement space, penalize it.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Progress-sensitive density adjustment:
    // As we approach the end of the stream, prioritize aggressive packing 
    // to minimize new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // New Bin Logic:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // calibrate the cost against the mean residual of existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing bins are already too crowded (low mean_residual)
        // or if we are very early in the stream.
        score = mean_residual + (progress * 50.0) + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
