    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic pressure: penalize bins that deviate from the mean residual to keep packing uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Encourage Best-Fit behavior: favor smaller post_residuals (tighter packing).
    // This is the baseline, already represented by score += post_residual.

    // If this is the only bin that fits the current item, prioritize it highly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New bin penalty: if the bin is empty (new bin candidate), add a significant cost
    // unless the current open bins are all very poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // Progress-based scaling: as we near the end of the stream, favor consolidation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to be useful for common items (e.g., < 10).
    // If post_residual is in the "dead zone" (1..9), add a heavy penalty to push the search towards better fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when existing ones have capacity.
    // As open_bins_count increases, we become more desperate to fit in current bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5).min(40.0);
    }

    // 3. Lookahead Alignment: If next_item_size is known, reward bins that can accommodate it.
    // If the current post_residual is a perfect or near-perfect fit for the next item, reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        if fit_diff < 5.0 {
            score -= 15.0;
        }
    }

    // 4. Global Efficiency: If the current bin is the only one that fits the item (fitting_bins_count == 1),
    // we should prioritize using it to avoid opening a new bin, unless the residual is extremely bad.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 20.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the mean efficiency of the pack.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
