pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating bins that are too "tight" (highly fragmented) vs "loose"
    // We want to minimize post_residual, but prioritize bins that leave enough room 
    // for future items (next_item_size).
    let fit_penalty = if post < next_item_size as f64 {
        post * 2.5
    } else {
        post * 0.8
    };

    // Interaction between mean_residual and current post_residual
    // Helps maintain balance across open bins
    let balance_factor = (post - mean_residual).powf(2.0) * 0.1;

    // Favor filling bins early in the stream, but be conservative near the end
    // to avoid leaving too many bins half-empty.
    let urgency = (1.0 - progress) * 10.0;

    // Penalty for opening a new bin: 
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // We add a threshold penalty that decreases as the stream progresses.
    let new_bin_penalty = if bin_residual == bin_capacity {
        45.0 + (progress * 20.0)
    } else {
        0.0
    };

    // Prefer bins that are "almost full" to minimize the number of open bins.
    let fill_efficiency = (bin_capacity - post_residual) as f64;
    let efficiency_reward = -fill_efficiency * 0.5;

    let mut score = fit_penalty + balance_factor + urgency + new_bin_penalty + efficiency_reward;

    // Strong incentive to use an existing fitting bin if only one is available
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
