    // 2. Penalty for creating "dead space": If post_residual is small but > 0, 
    //    it is harder to fill later. We penalize small non-zero remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If this bin fits the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Thresholding: If we are forced to open a new bin, penalize it unless 
    //    all existing bins have poor fits (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the current mean_residual is already very tight
            // or if the item is large (>= 70) and likely to struggle in existing bins.
            if mean_residual > 20.0 || item_size > 70 {
                score -= 10.0;
            } else {
                score += 100.0; // Strongly discourage opening new bins unnecessarily
            }
        }
    }

    // 5. Fitting Pressure: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Global progression: As we approach the end of the stream, prioritize 
    //    exhausting existing bins (reduce penalty for larger residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 15.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
