pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: minimize post_residual
    // 2. Penalty for creating "orphaned" bins (if this is the last fitting bin, prioritize filling it)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 3. Lookahead Matching: If post_residual perfectly accommodates next_item_size, reward heavily.
    // This is the core of the 2-step lookahead logic.
    if next_item_size > 0 {
