    // This maintains bin consistency and discourages creating high-fragmentation outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Logic: If this is an empty bin (new bin candidate), penalize it relative to
