    // Lower post_residual is better, but we penalize bins that become "too tight" 
    // early in the stream to preserve room for future large items.
    let mut score = post;

    // Penalty for creating a new bin:
    // If this is a new bin (bin_residual == bin_capacity), we add a heavy penalty 
    // that scales with the progress of the stream to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Interaction term: If the remaining space is small, we risk stranding a large item.
    // We penalize bins that leave a small, unusable gap (e.g., 1-5 units) 
    // by squaring the penalty, but only if the next item is large.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * (1.0 + (next_item_size as f64 / bin_capacity as f64));
    }

    // Lookahead influence: If the next item is large, favor bins that have 
    // enough space to accommodate it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state awareness: Reward bins that align with the current mean residual 
    // to maintain a uniform fill rate across the bin set.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Final adjustment: Penalize opening new bins if there are still many fitting bins available.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += (fitting_bins_count as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post-residuals to keep bins packed tightly.
    // We favor post_residuals that are small (close to 0).

    // 2. Harmonic Class Logic: 
    // If post_residual is small, it might be too small to fit future items. 
    // We penalize "dead zones" (e.g., 1-9) which are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Integration:
    // If we have a next_item, try to leave enough room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect alignment: reward bins that can accommodate the next item perfectly.
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.1;
        } else {
            // If the current placement makes the next item impossible, penalize slightly.
            score += 15.0;
        }
    }

    // 4. Distributional Awareness:
    // If we are late in the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 5. New Bin Penalty / Threshold:
    // When bin_residual == bin_capacity, this is a new bin. 
    // We heavily penalize opening a new bin unless the fit is absolutely terrible in all others.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 45.0;

        // If we have many open bins, opening another is very expensive.
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean residual.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20 range).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins unless the fit is extremely tight (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), increase cost significantly.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that have a residual close to the mean to maintain uniformity.
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.2;
    }

    // 4. Scarcity Constraint: If this is the only fitting bin, reduce its cost to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression scaling: As we near the end of the stream, prioritize closing bins (minimize open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

