    // If this bin is significantly emptier than the average, we prefer filling it to "clean up"
    // fragmented space.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression Weighting
    // Towards the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

