    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic for new bin creation:
    // If this is a new bin (bin_residual == bin_capacity), evaluate if we should wait
    if bin_residual == bin_capacity {
