            score += diff * 0.4;
        }

        // Penalize bins that deviate significantly from the global mean residual
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    // Dynamic horizon: towards the end of the stream, prioritize filling existing bins aggressively
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.3;
    }

    // If this is the last fitting bin, prioritize it to avoid creating a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
