    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prefer smaller post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: proportional to progress
    // As we near the end of the stream, we become more conservative about opening new bins
    if is_new_bin {
        score += (1.0 - progress) * 50.0;
        // If other bins can fit the item, heavily penalize opening a new one unless it's a perfect fit
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 - (item_size as f64 / bin_capacity as f64));
        }
    } else {
        // Non-linear interaction: reward fitting into bins that align with the mean residual
        // This encourages "clustering" items of similar sizes together
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead heuristic: if next_item_size is large, avoid leaving small residuals
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // High penalty for leaving "dead space" that cannot fit the next item
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // Penalize bins that are becoming too full if they prevent future fits
        // Quadratic penalty for very small residuals (potential fragmentation)
        if post_residual > 0 && post_residual < 10 {
            score += (10.0 - post_residual as f64).powi(2);
        }
    }

    // Global pressure: as open_bins_count grows, prioritize filling existing bins more aggressively
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
