pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space (residual < 10 is often unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic/Modulo optimization: Reward packing that leaves space for common item sizes
    // If post_residual is a multiple of 20, it is more likely to fit future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead coupling: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
