    }

    // 5. Density heuristic: Bias towards filling bins that are already closer to capacity
    // (Lower bin_residual implies higher density)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 6. Progression dampening: As the stream nears the end, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
