    // Discourage opening a new bin unless the current fit is terrible (high post_residual)
    // or the bin is highly fragmented.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if an existing one can fit the item,
            // unless the current average residual is already very low (bin packing density is high).
            score += 40.0 + (mean_residual * 0.5);
        }
        // As the stream progresses, become slightly more conservative about opening new bins
        score += progress * 20.0;
    } else {
        // Reward filling bins that are already "tight"
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // 4. Global State Influence
    // If we have many open bins, prioritize packing into existing ones to consolidate.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_f = bin_residual as f64;

