    // to force tighter packing later in the sequence.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + 50.0 * progress);

    // Best-Fit Decreasing logic: favor small post_residual (tight fit).
    // Penalize large post_residual exponentially to discourage creating "stranded" space.
    let fit_efficiency = post_res.powf(1.5);

    // Lookahead coupling: If next_item_size is large, penalize small post_residual 
    // to ensure we don't block the next item.
    let lookahead_penalty = if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_res < next_f {
            (next_f - post_res) * 2.0
