        0.0
    };

    // Global balance: penalize opening new bins if there are many open bins 
    // already struggling with low residual space (high mean_residual is good).
    let congestion_penalty = (1.0 / (mean_residual + 1.0)) * open_bins_count as f64 * 0.5;

    // Final score: lower is better.
    // We want to minimize the post_residual, but balance it against the lookahead 
    // and the cost of opening new bins.
    fit_efficiency + new_bin_penalty + lookahead_penalty + congestion_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
