    }

    // 5. Fragmentation Control:
    // If we only have one bin that can fit this item, we should generally take it
    // to avoid creating a new bin, unless the post_residual is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress Scaling:
    // As the stream nears completion, focus strictly on closing existing bins
    // rather than opening new ones to avoid stranded capacity.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (bin_residual == bin_capacity) as i32 as f64 * 60.0;
    }

    score
}

