    // 1. Penalize creating "dead space" that is too small for common items (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If post_residual perfectly matches or closely fits the next item, prioritize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that maintain enough space for the next item
            score -= (next_item_size as f64) * 0.2;
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 15.0;
        }
    }

    // 3. Balance usage: Avoid opening new bins if there are many open bins already.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If there are other bins that can fit the item, strongly penalize opening a new one
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean residual alignment: Favor bins that stay near the global average residual
    // to keep bin fullness uniform and reduce fragmentation.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize the residual space (Best-Fit principle)
    // post_residual is already the baseline. We refine it based on bin state.

    // 2. Lookahead Synergy: If the next item fits into the current bin's remaining space,
    // we prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Fragmentation Penalty: Penalize small slivers (dead space) that are hard to fill.
    // Optimal bins usually have residuals of 0 or > 20 (based on typical item distribution).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global Density Control: Balance the usage of open bins.
    // If we have many bins open, penalize opening new ones.
    if is_new_bin {
        score += 15.0 + (open_bins_count as f64 * 2.0);
        // Late game: be more aggressive to consolidate if possible
        if progress > 0.8 {
            score += 20.0;
        }
    } else {
        // If this bin is "tight" (low residual), favor it.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it 
    // to keep the bin count low.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 6. Mean Residual Calibration: Avoid bins that deviate significantly from average density.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but not zero, 
    // it's often harder to fill than a slightly larger residual.
    // We penalize the "near-zero" range (1-9) to force tighter packing.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: if the next item is large, favor bins with more space.
    // If next_item_size is 0 (end of stream), we prioritize closing bins.
    if next_item_size > 0 {
        let space_needed_next = next_item_size as f64;
        if post < space_needed_next {
            score += 25.0 * (1.0 - progress.powf(0.5));
        }
    }

    // New bin strategy: 
    // If this is a new bin (bin_residual == bin_capacity), calculate cost based on current congestion.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are highly fragmented
        // or if we are near the end of the stream and need to clear out.
        let fragmentation_penalty = (open_bins_count as f64 - mean_residual / 10.0) * 5.0;
        score = 45.0 + fragmentation_penalty + (progress * 20.0);
    } else {
        // If it's an existing bin, favor it if it's the only one that fits (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Non-linear coupling: penalize bins that deviate significantly from the mean residual
        // to keep bin levels balanced.
        let deviation = (post - mean_residual).abs();
        score += 0.2 * deviation.powf(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
