    // 3. Density Balancing: Avoid filling bins too early if we have many bins open
    // If we have many open bins, prioritize packing the most empty ones (Best Fit)
    // If we have few, prioritize filling the most full ones (First Fit)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if open_bins_count > 5 {
        score += fill_ratio * 10.0;
    } else {
        score -= fill_ratio * 10.0;
    }

    // 4. Harmonic Thresholding: Modulo logic for "comfortable" bin states
    // Prefer bin states that are multiples of 20 (common divisor of 100)
    let harmonic_mod = post_residual % 20;
    if harmonic_mod == 0 {
        score -= 15.0;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current fit is terrible
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low or we are early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 20.0);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

