            // If no bins fit, we have no choice, make this the baseline.
            score = 5.0; 
        }
    }

    // 5. Progress Weighting: As we approach the end of the stream, prioritize 
    // closing existing bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is highly likely to be wasted.
    // We penalize this heavily as these are difficult to fill with any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit into the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when capacity is available in existing ones.
    // If this is a new bin (bin_residual == bin_capacity), increase the cost significantly.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Compactness Bias: If this is the only bin that can fit the item, favor it to prevent
    // creating a new bin, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global Smoothing: Use the mean_residual to avoid fragmented bins.
    // If this bin's post_residual is significantly worse than the current average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
