    }

    // Lookahead interaction: If the next item can fit in the post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && post >= (next_item_size as f64) {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter 
    // to avoid needing new bins at the end.
    score += (progress * 15.0) * (post / bin_capacity as f64);

    // Global state awareness: If we have many open bins, penalize opening a new one.
    // bin_residual == bin_capacity represents the "New Bin" candidate.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is weighted by how many bins are already open
        // and how much room is left in existing ones.
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    }

