    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the current distribution of open bins is already crowded (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 60.0;
        } else {
            score += 30.0;
        }
    }

    // 4. Fitting Count Utility: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize tighter packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin (bin_residual == bin_capacity), we penalize it 
    // to force filling existing bins unless they result in extremely poor fits.
    if bin_residual == bin_capacity {
        score += 35.0; 
