    // 2. Lookahead optimization: If post_residual is close to next_item_size, 
    // prioritize this bin to create a "perfect" fit for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 20.0 * (1.0 / (1.0 + diff));
    }

    // 3. Efficiency penalty: If this is the only bin that fits the current item, 
    // we should prioritize it significantly to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. Residual balancing: Penalize creating residuals smaller than the average 
    // item size (estimated by bin_capacity / 3) to prevent fragmentation.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // 5. Global state normalization: As we approach the end of the stream, 
    // become more aggressive in packing to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    // 6. Penalty for creating "dead zones" that are unlikely to fit future items.
    // If the post_residual is significantly below the mean_residual, it is 
    // considered a "tight" bin.
    if (post_residual as f64) < mean_residual {
