    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Baseline: Lower post_residual is generally better (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments smaller than the smallest likely future item).
    // If post_residual is small but > 0, it's often a poor fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dynamic Lookahead: If the next item fits into the current post_residual, 
    // reward this bin heavily to preserve capacity for future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Progression Awareness: As the stream nears the end, we become more aggressive 
    // in fitting items into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // Global State: If this bin is the only one that can fit the item, 
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty for opening a new bin:
    // When bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    // We add a threshold to make opening a new bin expensive unless the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64 * 0.5);

        // If we have many open bins already, we prefer to reuse them rather than opening new ones.
        if open_bins_count > 5 {
            score += 10.0;
        }
    }

    // Balance against global mean: If this bin's residual is significantly better than 
    // the current average residual, prioritize it to keep bin states consistent.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for leaving "dead zones": residuals smaller than the smallest possible item size are often wasted.
    // We penalize small residuals more heavily as the stream progresses.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, avoid bins that leave too little space for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // New bin logic: if this is a new bin (bin_residual == bin_capacity), 
    // only open it if fitting_bins_count is low or the current state is highly fragmented.
    if bin_residual == bin_capacity {
        // Higher threshold to open a new bin as we reach the end of the stream
        let threshold = 20.0 + (progress * 30.0);
        score += threshold;
    } else {
        // Reward bins that bring the current bin residual closer to the global mean,
        // which helps keep bin utilization balanced.
        score += (post - mean_residual).abs() * 0.5;
    }

    // Penalize creating excessive open bins early in the stream
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // but reward those that leave space for the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit synergy: reward when we can fit the next item perfectly
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // 2. Harmonic/Modulo pressure: Avoid creating "sliver" residuals (1-9) which are hard to fill.
    // If post_residual is in the "dead zone" [1, 9], penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Fragmentation control: If we have many bins open, prioritize filling existing ones.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.1;
    }

    // 4. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only consider opening it if the fitting_bins_count is low or if the 
    // current item is large and would create a very poor fit in existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Necessary to open new bin
        } else {
            // Penalize opening a new bin if we have options, scaled by progress
            score += 40.0 + (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    // 5. Mean-based balancing: Reward bins that keep us close to the mean_residual
    // to keep bin utilization uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

