    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Prefer tighter fits (Best-Fit principle)
    // We already have post_residual in score, which naturally favors smaller residuals.
    // We add a slight bias against very large residuals.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
