    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals in the range (0, 10), as they are rarely useful.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item is large and won't fit in the current post_residual,
    // we penalize this placement to save space for the next item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic thresholding based on stream progress.
    // Early in the stream, we are aggressive about packing (low score).
    // Late in the stream, we become more conservative to avoid opening new bins.
    let progress_factor = 1.0 + (progress * 2.0);
    score *= progress_factor;

    // Favor bins that have a residual close to the mean residual of all open bins.
    // This helps maintain a uniform "fill level" across bins, reducing variance.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 0.2;

    // If this is the only bin that can fit the item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // If considering a new bin, apply a significant base penalty to force
    // the heuristic to prefer existing bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
