    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: penalize opening new bins unless the fit is perfect.
    // If this is a new bin (bin_residual == bin_capacity), apply a baseline cost.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins already, make opening a new one even more expensive.
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Fitting constraints: if this is the last chance for this item (fitting_bins_count == 1),
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual alignment: prefer bins that keep their residual close to the global mean,
    // balancing the load across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

