    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        score += 35.0 + (progress * 40.0);
    } else {
        // Reward using existing bins, proportional to how much they deviate from the mean.
        score -= (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item,
    // strongly incentivize picking it to prevent premature bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
