pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: the remaining space after placement.
    // Lower post_residual means a tighter fit (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        // Only open a new bin if the current mean residual of open bins is very low,
        // suggesting we are "clogging" existing bins, or if there is no other choice.
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
