                score += 15.0;
            } else if post_residual >= next_item_size {
                // This leaves room for the next item. Reward it.
                score -= 5.0;
            }
        }
    }

    // Global state adjustment: If many bins are open, try to consolidate.
    // Penalize using open bins that are already mostly empty.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (1.0 - fill_ratio) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
