        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // If this is the only fitting bin, we are forced to use it unless the new bin score is lower
    // We adjust the score to make "forced" bins slightly more attractive to avoid unnecessary new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize opening a new bin if we have plenty of capacity in existing bins
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Higher penalty if we are early in the stream to encourage consolidation
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // Adjust based on mean_residual to favor bins that pull towards the global average
    // This helps maintain a uniform distribution of fill across all bins
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff.abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin utilization density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 250.0;
    }

    // 3. Open bins pressure: If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. Mean residual equilibrium: Favor bins that keep the overall mean residual 
    // closer to the item size average to maintain uniform bin aging.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.5;

    // 6. Progress scaling: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any potential future item (below 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: reward bins where the post_residual is close to the next_item_size.
    // We prioritize bins that leave exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 20.0;
        }
    }

    // 3. Density management: Prefer bins that align with the current mean residual.
    // This keeps the remaining space in open bins somewhat uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Force efficiency: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin logic: Only open a new bin if the current fit is extremely poor (large post_residual).
    // The new bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only open new if we have many bins already and this item is 'awkward' for existing ones.
        if open_bins_count > 0 {
            score += 60.0; 
        }
    }

    // 6. Progress weight: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
