    // We heavily penalize residuals that are smaller than the smallest likely item (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Lookahead logic: if next item is large, favor bins that can accommodate it.
    // If the current post_residual cannot fit the next item, penalize the choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Global state: if we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity (New Bin candidate), add a hefty penalty based on open_bins_count.
    if bin_residual == bin_capacity {
