    }

    // Dynamic thresholding: if this is the only bin that fits, prioritize it, 
    // unless the residual is extremely inefficient.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Balance the mean residual: favor bins that keep the average residual high 
    // to prevent fragmenting bins too early.
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    } else {
        score -= 5.0;
    }

