    // We use a quadratic penalty on the post_residual to favor tight fits (Best Fit principle).
    let mut score = post * post;

    // Lookahead logic: If the next item is large, we want to leave more space in the current bin
    // if the current bin is already tight, OR we want to clear the current bin if the next 
    // item won't fit anywhere.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 - post) * (next_item_size as f64 - post);
        score += if post < next_item_size as f64 { lookahead_penalty * 0.5 } else { -lookahead_penalty * 0.2 };
    }

    // Dynamic thresholding: Near the end of the stream, prioritize closing bins
    // by penalizing the creation of new bins (represented by bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 1500.0 * (1.0 + progress);
        score -= (open_bins_count as f64 * 10.0);
    }

    // Interaction with mean_residual: If this bin's post_residual is significantly 
    // higher than the average, it is a poor candidate (wasteful).
    if post > mean_residual {
        score += (post - mean_residual) * 5.0;
    }

    // If this is the only bin that can fit the item, give it a significant boost
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2000.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Base score is post_residual.
    // Smaller post_residual is better, but we apply non-linear penalties.

    // 2. Penalty for creating "stranded" space:
    // If the post_residual is small (e.g., < 10), it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If next_item_size fits in the post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 4. Harmonic class bias:
    // Favor bins that align with common item size distributions (multiples of 20, 25, 50).
    let alignment = post_residual % 25;
    if alignment == 0 {
        score -= 5.0;
    }

    // 5. Global state normalization:
    // If we have many open bins, prioritize closing them (Best-Fit).
    // If we have few open bins, be more selective (Best-Fit).
    if fitting_bins_count == 1 {
        // This is the "Last Chance" to fit without opening a new bin.
        score -= 15.0;
    }

    // 6. New bin throttle:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless the item size is very large (e.g., > 70) or we have no fitting bins.
    if bin_residual == bin_capacity {
        score += 30.0; 
        if item_size > 70 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // 7. Progression factor:
    // As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

