    // Lookahead logic: if next item is large, prioritize keeping space open.
    // If next_item_size is 0, we are at the end, so prioritize filling bins.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64 / bin_capacity as f64);
        // If post_residual is too small to fit the next item, penalize slightly
        if post_residual < next_item_size {
            score += lookahead_pressure * 20.0;
        }
    }

    // Dynamic coupling: shift strategy based on stream progress
    // Early stage: prioritize packing efficiency. Late stage: prioritize minimizing bin count.
    score -= (1.0 - progress) * (bin_capacity as f64 - post_res) * 0.1;

    // Penalize bins that deviate significantly from the mean residual to encourage uniform packing
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo logic: reward post_residuals that allow future items
    // If post_residual is small but not zero, it creates "unusable" gaps.
    if post_residual > 0 && post_residual < 10 {
