            score += 10.0;
        }
    }

    // 3. Density Management: Balance filling bins vs. keeping them open.
    // If we have many open bins, prioritize filling existing ones (Best Fit).
    if open_bins_count > 0 {
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization * 10.0;
    }

    // 4. Thresholding: Make opening a new bin expensive unless necessary.
    // If this is a new bin (residual == capacity), penalize it based on how many
    // other bins could have taken the item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 30.0;

        // As the stream progresses, make opening new bins slightly more expensive
        // to encourage packing density in the final stages.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean residual alignment: Favor bins that stay near the average residual
    // to keep the bin landscape uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
