    let base_score = post_res_f + lookahead_match + fragmentation_penalty + new_bin_penalty;

    // Adjust for the scarcity of fitting bins. If this is the only bin that fits,
    // reduce the score to ensure we don't unnecessarily open a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        base_score - 15.0
    } else {
        base_score
    }
}

