            score += (post_residual as f64) * 0.2;
        }
    }

    // Heuristic for new bin creation (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing bins are quite full (mean_residual is low)
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // Harmonically weight bins that are already near capacity to finish them off
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Adjust score based on total stream progress to favor tighter packing early on
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range (0, 10), it creates "fragmentation" that is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Open Bins Pressure: Penalize opening a new bin if we have many bins open already
    // Force consolidation by increasing the cost of a new bin as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 5.0;
    }

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual,
    // prioritize this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Fitting Scarcity: If this is the ONLY bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual balance: Avoid bins that deviate significantly from the mean 
    // to keep the packing density uniform across all active bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

