    // If we have a next item, try to leave a post_residual that fits it perfectly.
    // If post_residual is close to next_item_size, we reward it.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
