            score += 20.0;
        }
    }

    // 4. Global balance: avoid creating bins with residuals far from the current mean
    // This encourages uniformity across bins to increase probability of future fits.
    let residual_variance = (post_residual as f64 - mean_residual).abs();
    score += residual_variance * 0.5;

    // 5. Progression scaling: towards the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
