    // or we are near the end of the stream where efficiency is less critical than packing speed.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only pick if fitting_bins_count is low or if current open bins are very full.
        score += 25.0; 
        score -= (progress * 15.0); // Toward the end, be more willing to open new bins to clear items
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // Existing bin logic: Reward bins that are already "half-full" to keep them active
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
