pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle).
    // Penalize small residuals that are unlikely to fit future items (e.g., < 10).
    // The "Dead Space" penalty is non-linearly scaled by progress to encourage 
    // tighter packing early and aggressive consolidation late.
    let mut score = post;

    // Penalty for creating a "sliver" (unusable space < 10)
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
    }

    // Lookahead interaction: If the next item could fit in the current post_residual,
    // strongly reward that bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
