    // (where bin_residual == bin_capacity) to force consolidation.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Exponential penalty for opening new bins as the stream nears completion
            score += 50.0 * (1.0 + progress.powi(2)) * (open_bins_count as f64).sqrt();
        }
    } else {
        // If this bin is the last chance for the current item, reward it to avoid
        // opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Variance penalty: discourage bins that deviate significantly from the mean_residual
    // to keep bin fill levels balanced.
    score += (post - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
