            score -= 45.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        } else {
            // Penalize bins that leave a gap too small for the next item.
            score += 30.0;
        }
    }

    // 3. Global State: If we have many open bins, prioritize packing tighter (lower post_residual).
    // If we have few, we can afford to be slightly more wasteful to keep options open.
    let density_penalty = (open_bins_count as f64) * 2.5;
    score += density_penalty;

    // 4. Fragment Avoidance: If post_residual is in the "danger zone" (e.g., 1-9),
    // it's hard to fill later. Penalize this specifically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 5. Mean Residual Alignment: If this bin's post-residual is significantly 
    // worse than the average, penalize it to encourage homogenization.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
