    // Penalize creating bins with very small, unusable residual space ("slivers").
    let mut score = post * post;

    // Favor bins that are "tight" relative to the lookahead.
    // If the next item fits into the current post_residual, reward the placement.
    if next_item_size > 0 && (post_residual >= next_item_size) {
