        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Dynamic pressure: discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty to prevent opening a new bin if an existing one can hold the item
        if fitting_bins_count > 0 {
            score += 200.0;
        }
        // Penalize opening a new bin more as the stream progresses
        score += (step_index as f64 / total_items as f64) * 40.0;
    }

    // 3. Lookahead optimization: prioritize bins that leave space for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tight fits that leave exactly enough room for the next item
        let diff = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 / (1.0 + diff));
    }

    // 4. Balance load across bins: penalize bins that deviate significantly from the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Prefer filling bins that are already "fragmented" (low residual) to keep others empty
    // Inverse relationship: lower residual = lower score (higher priority)
    score -= (bin_capacity - bin_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
