    }

    // 5. Urgency: If this is the last chance to fit an item into existing infrastructure,
    // be less picky about the residual space.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive with fitting.
    if progress > 0.8 {
