    // (assuming 10 is the lower bound of item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Harmonic Alignment: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps maintain "clean" remaining space for future items.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 5. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current fitting options are extremely poor (i.e., high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
