    // 3. Lookahead logic: If the next item can fit perfectly or near-perfectly into the post_residual, 
    //    heavily reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fit_diff = (post_residual - next_item_size) as f64;
            // Reward bins that leave exactly enough room for the next item
            score -= (100.0 - fit_diff) * 2.5;
        }
    }

    // 4. Thresholding: Penalize "near-empty" bins unless necessary.
    // If we have many open bins, penalize opening a new one or using a very empty bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0; // Strong discouragement for opening new bins prematurely
        }
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, 
    //    heavily prioritize it (reduce score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 6. Mean Residual Balancing: Avoid creating bins that are outliers compared to the average.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

