    }

    // 4. Density Balancing: Avoid creating bins that deviate significantly from 
    // the mean_residual of the current open set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless the 
    // current fits are extremely inefficient (e.g., leaving a tiny unusable gap).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the average residual is already high 
            // or if we are very early in the stream.
            score += 45.0 - (mean_residual * 0.3);
        } else {
            score = 0.0; // Must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
