    }

    // 5. New Bin threshold: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the current open bins are all poor fits (high post_residual).
    if bin_residual == bin_capacity {
        score += 25.0; // Baseline cost to open a new bin

        // If we have many open bins that are already quite empty, don't open another one.
        if open_bins_count > 0 && mean_residual > 40.0 {
