}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Best-Fit Decreasing logic: reward smaller post_residual (Best Fit)
    // Penalize new bins heavily early on, but allow them if the fit is poor elsewhere
    let mut score = post;

    // Non-linear coupling: penalize large post_residual exponentially as the stream progresses
    // This forces tighter packing as we reach the end of the stream
    score += (post * post / bin_capacity as f64) * (1.0 + progress);

    // Lookahead penalty: if the next item is large, avoid leaving a small gap that makes it unusable
    if next_item_size > 0 && post < next_item_size as f64 && post > 0.0 {
        score += (next_item_size as f64 - post) * 2.0;
    }

    // New bin penalty: adjust based on how many bins are already open and the progress
    if is_new_bin {
        // Base penalty for opening a new bin, scaling down slightly as we progress 
        // to avoid being left with many half-empty bins at the end
        score += (bin_capacity as f64 * 0.5) * (1.0 - (progress * 0.3));

        // If we have many fitting bins, it is almost never optimal to open a new one
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 20.0;
        }
    } else {
        // If it's an existing bin, reward it if its residual is close to the mean
        // This encourages "clustering" items into bins with similar profiles
        let dev = (residual - mean_residual).abs();
        score -= dev * 0.1;
    }

    // Safety valve: if this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
