    // Progress coupling: As the stream progresses, tighten the constraint on 
    // opening new bins by increasing the cost of empty bin selection.
    let new_bin_cost = if bin_residual == bin_capacity {
        50.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Fitting constraint: If this is the only bin that fits the item, make it highly attractive.
    let scarcity_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
