    // 3. Balancing: Favor bins that align with the current mean residual to keep bin states uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Scarcity management: If this is the last fitting bin, prioritize filling it to avoid opening a new bin
