    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If next_item_size exists, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // 4. Global state pressure:
    // If we have many open bins, discourage opening a new one unless the fit is very poor.
    if is_new_bin {
        if open_bins_count > 0 {
            // High penalty for opening new bins if we have space elsewhere.
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If it's an existing bin, favor bins that are already "tight" to keep others open.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this is the only bin that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Dynamic balancing:
    // As the stream progresses, prioritize closing bins (lower mean_residual) to keep density high.
    score += (mean_residual - post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
