    // Penalize creating bins that are too empty early on, but allow tighter packing later.
    // We aim for "Best Fit" behavior modified by a lookahead-aware pressure.
    // If post_residual is 0, it's a perfect fit (reward heavily).
    let mut score = post_res.powf(1.5);

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a cost based on 
    // the current number of open bins and the progress of the stream.
    if bin_residual == bin_capacity {
