        // As progress increases, the cost of opening a new bin decreases to prioritize 
        // finishing the packing process.
        score += (open_bins_count as f64 * 20.0) * (1.0 - progress);

        // If the item fits in an existing bin, penalize the new bin option even more.
        if fitting_bins_count > 0 {
