    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Coupling: Reward placing items that leave room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize bins that block the next item from fitting
            score += 15.0;
        }
    }

    // 4. Fitting Density: If this is the only bin left that fits the current item, prioritize it
    // to avoid the penalty of opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Global Efficiency: Discourage creating bins with residuals significantly below the current mean
    if !is_new_bin && (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
