    let balance_penalty = (post - mean_residual).abs() * 0.2;

    // Final score: Lower is better.
    // Base score is post_residual, adjusted by the non-linear factors.
    let score = post + fragmentation_penalty + lookahead_reward + new_bin_penalty + balance_penalty;

