        score += progress * 30.0;
    }

    // 4. Fitting Density: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean.
    // This helps maintain a uniform "tightness" across all bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice (bin_residual == bin_capacity) using progress 
    // to encourage consolidation as the stream nears completion.
    let is_new_bin = bin_residual == bin_capacity;
    let base_new_bin_penalty = 60.0 + (progress * 40.0);

    // Non-linear coupling: Favor small post_residual (Best Fit), but penalize 
    // extremely tight fits if a lookahead item is large.
    let mut score = post * 1.5;

    // Penalize the "New Bin" specifically
    if is_new_bin {
        score += base_new_bin_penalty;
    }

    // Penalty for creating "dead space": if post_residual is small but unusable
    // (e.g., < 10), it is often better than a large gap, but if we have 
    // lookahead data, we reward fits that leave exactly enough space for it.
    if next_item_size > 0 {
        let diff = (post as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that can accommodate the next item perfectly
        if post >= next_item_size as f64 {
            score -= (1.0 / (1.0 + diff)) * 25.0;
        } else {
            // Strong penalty for bins that cannot fit the next item when they could have
            score += 15.0 * (1.0 - progress);
        }
    }

    // Discourage opening too many bins early on by penalizing high open_bins_count
    // relative to the mean_residual.
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // If this is the last bin that can fit the item, prioritize it to avoid
    // unnecessary bin creation, weighted by how much space it leaves.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (the standard Best-Fit approach)
    // We favor bins that leave the smallest residual space.
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Lookahead: If a future item exists, prioritize bins that can accommodate it.
    // If the current bin cannot fit the next item, we penalize it exponentially.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that leave exactly enough space for the next item (harmonic alignment)
            score -= (100.0 / (1.0 + (post_residual - next_item_size) as f64));
        }
    }

    // 3. New Bin Logic: Discourage opening a new bin unless the current residual is very poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if the item fits poorly elsewhere.
        // We set a threshold cost for opening a new bin relative to total items.
        score += 45.0 + (open_bins_count as f64 * 0.1);
    } else {
        // 4. Fitting Pressure: If this is the only bin that fits the current item, 
        // aggressively lower the score to ensure we don't open a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Global Mean Alignment: Avoid creating bins that are outliers compared to the current mean.
    // This helps maintain a uniform density across all open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
