pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: minimize post_residual (already in score).

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, we favor this bin.
    // We penalize bins where the post_residual is too small to fit the next item effectively.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
