            score += next_item_size as f64 * 0.2;
        }
    }

    // 3. Avoid Fragmentation: Penalize bins that create "dead zones" (small remainders that are hard to fill).
    // If the post_residual is small but > 0, it's often better to have a larger residual or zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly lower than the global mean,
    // we are packing it tighter than average, which is generally good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Threshold: Discourage opening new bins unless the fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), add a significant overhead cost.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 6. Last Resort Logic: If this is the only bin that fits, we must take it (reduce score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progress Weighting: As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
