    // As the stream progresses, we become more aggressive in opening new bins to optimize packing.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + 40.0
    } else {
