    };

    // Reward placing items into bins that result in a post_residual that is either 0 (perfect fit)
    // or large enough to accommodate the next item.
    let fit_bonus = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            // Reward potential future fit: cubic decay to favor tighter fits
            -20.0 * (1.0 - (post - next_item_size as f64) / 100.0).powi(3)
        } else {
