        post * 0.5
    };

    // Penalize bins that deviate significantly from the mean_residual to keep residuals uniform
    let uniformity_penalty = (post - mean_residual).abs() * 0.2;

    // Favor bins that are near exhaustion (low post_residual) but only if they are not 
