    let desperation_penalty = if fitting_bins_count == 1 && !is_new_bin {
        -50.0 // Strong incentive to use the last available bin before opening a new one
    } else {
        0.0
    };

    post + new_bin_penalty + fit_bonus + uniformity_penalty + desperation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
