pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize small remainders (fragmentation) by adding a non-linear inverse term.
    // If post_residual is very small (< 5), it creates "dead space" that rarely fits future items.
    let fragmentation_penalty = if post < 5.0 && post > 0.0 {
