    // unless the current fit is extremely poor (large fragmentation).
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Must open
        } else {
            50.0 + (progress * 50.0) // Discourage opening new bin as stream progresses
        }
    } else {
        0.0
    };

    // Coupling: Use mean_residual to favor bins that are already "tight" 
    // to keep the bin landscape uniform.
    let uniformity_factor = (post - mean_residual).abs() * 0.2;

    let mut score = post + fragmentation_penalty + lookahead_reward + new_bin_penalty + uniformity_factor;

