    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. New-bin thresholding: Only open a new bin if the current mean residual is already
    // quite low (bins are full), or if the current item is very large.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Must open first bin
        } else {
            // Penalize opening new bins unless the current bins are very tightly packed
            score += (mean_residual * 2.0) + (item_size as f64 * 0.8);

            // If the next item is large, opening a new bin is less penalized
            if next_item_size > 70 {
                score -= 30.0;
            }
        }
    } else {
        // 4. Best-Fit Decreasing logic: Favor bins that leave the smallest post_residual
        // but penalize if it leaves a "sliver" that can't fit anything.
        if post_residual == 0 {
            score -= 20.0; // Perfect fit bonus
        }

        // 5. Lookahead synergy: If the current placement leaves room for the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // 6. Global pressure: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
