pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-placement residual (Best Fit)
    // We add a penalty for "Dead Space" (residual < next_item_size)
    let dead_space_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Non-linear coupling: As the stream progresses, we become more aggressive
    // about filling bins tightly to avoid trailing empty bins at the end.
    let progression_factor = 1.0 + (progress * 2.0);

    // Penalty for opening new bins: if bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize this heavily early on, but reduce the penalty as the stream progresses
    // to allow for better packing configurations that aren't possible with current open bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Reward bins that have residuals closer to the mean_residual of other bins
