    // If this is the only bin that fits, prioritize it significantly.
    let scarcity_bonus = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    let score = (post * progression_factor) 
                + dead_space_penalty 
                + new_bin_penalty 
                + uniformity_bonus 
                + scarcity_bonus;

    score
}

