    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin logic:
    // Only open a new bin if the current bin's mean_residual is already very low,
    // making it unlikely to fit future items.
    if bin_residual == bin_capacity {
