    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with open_bins_count and progress.
        // Opening a new bin is expensive, but necessary if all others result in poor fits.
        score += (open_bins_count as f64 * 10.0) + (progress * 20.0);
    } else {
        // Reward utilizing existing bins to keep mean_residual balanced.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Extreme fit bonus: Perfect fit is always the priority.
    if post_residual == 0 {
        score -= 50.0;
    }

