    // 5. Global state normalization: Penalize bins that deviate from the mean 
    // residual to encourage uniformity across the bin set.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" that is too small for most incoming items.
    // If post_residual is very small (e.g., 1-9), it is often worse than leaving 
    // a slightly larger space, as 10 is the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead coupling: If the next item is large, prioritize bins that have
    // enough space to accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64) * 0.2;
        }
    }

    // Progression scaling: As we approach the end of the stream, prioritize 
    // filling existing bins more aggressively to consolidate space.
    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is the only bin that can fit the item, heavily incentivize choosing it
    // to avoid the overhead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Heuristic for new bin: If bin_residual == bin_capacity, this is a new bin.
    // We penalize opening a new bin unless the existing bins provide very poor fits.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual of open bins is already quite low,
        // or if we are early in the stream.
        score += 40.0 + (mean_residual * 0.5) - (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // 2. Penalty for "Wasted" space: If post_residual is small but not zero (e.g., < 10), 
    //    it creates a "dead zone" that is hard to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 3. Lookahead integration: Try to match the next item with the current residual.
    // If we can fit the next item perfectly (or close to), prioritize this bin.
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Reward bins that leave exactly enough for the next item
            score -= (100.0 - (diff as f64 * 2.0));
        } else {
            // Penalize bins that cannot fit the next item if they are the only option
            score += 10.0;
        }
    }

    // 4. Harmonic/Fractional stability: 
    // Discourage opening a new bin if we have many bins with decent space.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very full
        score += 40.0 + (open_bins_count as f64 * 2.0);

        // If current mean_residual is large, we shouldn't be opening new bins
        if mean_residual > 20.0 {
            score += 50.0;
        }
    }

    // 5. Progression awareness: 
    // Towards the end of the stream, be more aggressive to consolidate bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Last chance logic:
    // If this is the only bin that can fit, prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals (1..9) are highly undesirable
    // because they are unlikely to fit most items (1..100) in future steps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // Dynamic pressure: If we are near the end of the stream, prioritize packing tightly.
    let progress = step_index as f64 / total_items as f64;

    // If this is a new bin, apply a threshold penalty based on how many bins are already open.
    // This discourages opening new bins unless the fit is very good or we have few bins open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + (progress * 15.0);
    } else {
        // Reward bins that are closer to the mean_residual to keep bin occupancy balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Lookahead logic: If the next item is large, avoid leaving a small residual.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 20.0;
    }

    // If this is the last fitting bin, grant a slight bonus to force completion of the bin
    // rather than opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Best-Fit logic: prioritize bins where post_residual is small
    // We penalize larger post_residuals to encourage tight packing.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead optimization: If next_item_size fits in post_residual,
    // heavily reward this bin to create a "perfect" pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.2;
        // Further refine: if it's a near-perfect fit (residual < 5), prioritize highly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 4. Global state awareness:
    // If we have many open bins, penalize opening new ones more aggressively.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
    }

    // 5. Residual balancing:
    // Avoid creating bins that are significantly below the mean_residual,
    // as these are "starved" bins that likely won't fit future items.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // 6. Urgency:
    // If this is the last chance to fit the item (fitting_bins_count == 1), 
    // reduce the penalty for a poor fit to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic).
    // Already baseline in score. We reward smaller post_residual.

    // 2. Lookahead Synergy: If the next item fits into the post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless existing options are poor.
    if bin_residual == bin_capacity {
        // If we have many fitting bins, opening a new one is inefficient.
        if fitting_bins_count > 0 {
            score += 50.0 + (fitting_bins_count as f64 * 5.0);
        }
        // If we are late in the stream, favor closing bins (lower residual).
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 4. Global Density Balance: Avoid creating bins with residuals far from the mean.
    // This promotes uniform filling across all open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Fragmentation Avoidance: If post_residual is small but > 0, it's often wasted space.
    // Penalize "slivers" (e.g., 1-9) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Last-Chance Logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle).
    // Lower residual is generally better (tighter packing).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // New bins are penalized by a factor that scales with progress and the "difficulty"
        // of fitting items into existing space.
        let new_bin_penalty = 25.0 + (progress * 40.0) + (mean_residual * 0.5);
        score += new_bin_penalty;
    } else {
        // Coupling: If we have very few bins that can fit the current item, 
        // we should prioritize using them to avoid stranding items.
        if fitting_bins_count <= 1 {
            score -= 15.0; 
        }

        // Lookahead heuristic: If the next item is large, avoid leaving a tiny, unusable 
        // residual in the current bin if possible.
        if next_item_size > 0 {
            let space_after_next = post_residual as i32 - next_item_size as i32;
            if space_after_next >= 0 && space_after_next < 10 {
                // Penalize placements that leave a "dead zone" (too small for any item)
                // if the next item could have potentially fit better elsewhere.
                score += 20.0 * (1.0 - (space_after_next as f64 / 10.0));
            }
        }
    }

    // Non-linear interaction: Penalize high residual variance 
    // (keeping bins at similar utilization levels improves future fitting).
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward filling bins to "clean" thresholds (e.g., multiples of 20)
    // This reduces the number of small-fragment bins that are hard to fill later.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.8;

    // 3. Lookahead Integration: If the next item fits into the current post_residual, 
    // we heavily reward this placement to chain items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Reward creating a perfect fit for the next item
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // 4. Scarcity/Density Heuristic: 
    // If few bins can fit the current item, prioritize using them to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin is a good fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Increase penalty for opening a new bin as we progress through the stream
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that significantly deviate from the average residual of open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is small (1-9), it becomes unusable for 
    // the guaranteed range (10-80). We penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit Bias: Favor bins where the post_residual is minimized (Best-Fit principle).
    // The base score (post_residual) already incentivizes this, but we reinforce it.
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Integration: If the next item cannot fit into this specific post_residual,
    // we penalize this bin to encourage saving it for items that might fit better later.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Global Pressure: As the stream progresses, increase the cost of opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Discount the penalty if there are no other viable options
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // 5. Mean Residual Balancing: Penalize bins that are significantly "emptier" 
    // than the current average to discourage scattering items across too many bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize empty bin creation (the "new bin" candidate)
    if bin_residual == bin_capacity {
        score += 45.0;
        // Reduce penalty if no other bins are available
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 2. Best-Fit logic: prioritize bins that leave the smallest residue (Best-Fit principle)
    // Already partially handled by post_residual, but we refine it.

    // 3. Lookahead Matching:
    // If the next item can fit in the post_residual, drastically reduce score (prioritize)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it is a "tight" fit (leaving less than 10 units)
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }

    // 4. Dead Space Avoidance:
    // If the remaining space is small but unusable (e.g., < 10), penalize it 
    // unless it is a perfect fit (post_residual == 0)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global state balancing:
    // If we have many open bins, prioritize clearing them (Best-Fit)
    // If we have very few, be more conservative (First-Fit-like)
    if open_bins_count > 5 {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // 6. Last-Chance Logic:
    // If this is the only bin that can fit the current item, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 50.0;
    }

    score
}
